// Світло ЖК Республіка — установник v1.0.1. Не змінює вже наявні журнали світла.
const VERSION='2.0.0';
const ADDRESSES=["Т4А", "ТР1", "ТР3", "РК2А", "ТР5", "РК4", "РК6", "ТР4", "БШ7", "БШ9", "БШ10/8", "РК10", "БШ8"];
const SOURCES={"Світло вдома.js":"try{await importModule('Республіка · API').sync();}catch(e){console.log('API: '+e);}\n// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: orange; icon-glyph: magic;\n// Scriptable — Світло вдома. Works with Shortcuts > Run Script > Texts.\nconst fm = FileManager.local();\nconst dir = fm.documentsDirectory();\nconst stateFile = fm.joinPath(dir, 'light-home-api-v2.json');\nconst historyFile = fm.joinPath(dir, 'light-history-api-v2.json');\nconst now = Date.now();\nconst fmAD=fm;\n\n// Shared RK10 adaptation data. All original files are retained.\nconst AD_PENDING=fmAD.joinPath(fmAD.documentsDirectory(),'rk10-adaptive-pending.json');\nconst AD_RULES=fmAD.joinPath(fmAD.documentsDirectory(),'rk10-adaptive-rules.json');\nconst AD_LOG=fmAD.joinPath(fmAD.documentsDirectory(),'rk10-adaptive-log.json');\nfunction adRead(path,fallback){try{const a=JSON.parse(fmAD.readString(path));return a&&typeof a==='object'?a:fallback;}catch(_){return fallback;}}\nfunction adWrite(path,data){fmAD.writeString(path,JSON.stringify(data,null,2));}\nfunction adNorm(s){return String(s||'').toLowerCase().replace(/[’‘`]/g,\"'\").replace(/[‐‑‒–—−]/g,'-').replace(/\\s+/g,' ').trim();}\nfunction adAlert(kind,message,reason){\n  let now=Date.now(), list=adRead(AD_PENDING,[]);if(!Array.isArray(list))list=[];\n  const norm=adNorm(message), key=kind+'|'+norm;\n  const last=list.find(x=>x.key===key&&now-x.at<30*60000);\n  if(last)return;\n  list.push({id:'p'+now+'-'+Math.floor(Math.random()*10000),key,kind,at:now,message:String(message).slice(0,6000),reason,status:'pending'});\n  adWrite(AD_PENDING,list.slice(-100));\n  let log=adRead(AD_LOG,[]);if(!Array.isArray(log))log=[];\n  log.push({at:now,kind,reason,preview:String(message).slice(0,500)});adWrite(AD_LOG,log.slice(-200));\n  try{let n=new Notification();n.title='⚠️ РК10 · Перевір повідомлення';n.body=reason+'. Відкрий «РК10 · Перевірка повідомлень».';n.sound='default';let p=n.schedule();if(p&&p.catch)p.catch(e=>console.log('Сповіщення: '+e));}catch(e){console.log('Сповіщення: '+e);}\n}\nfunction adRules(kind){let o=adRead(AD_RULES,{});return Array.isArray(o[kind])?o[kind]:[];}\n\nlet s = {status:'unknown',since:null,lastOutage:null,lastSeen:null};\nif (fm.fileExists(stateFile)) {\n  try { s = {...s,...JSON.parse(fm.readString(stateFile))}; } catch (_) {}\n}\nlet history = [];\nif (fm.fileExists(historyFile)) {\n  try { const value = JSON.parse(fm.readString(historyFile)); if(Array.isArray(value)) history=value; } catch (_) {}\n}\nhistory = history.filter(e=>e && (e.status==='on'||e.status==='off') && Number.isFinite(e.at))\n  .sort((a,b)=>a.at-b.at);\nfunction dur(ms) {\n  const n=Math.max(0,Math.floor(ms/60000));\n  const d=Math.floor(n/1440),h=Math.floor(n%1440/60),m=n%60;\n  return (d?d+' дн ':'')+(h?h+' год ':'')+m+' хв';\n}\nfunction clock(t) {return new Date(t).toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'});}\nconst rk10=/#?\\s*[РP][КK]\\s*10(?![\\p{L}\\p{N}])/iu;\nfunction reportedStart(line,received) {\n  // When a bot supplies its own duration, its time is more reliable than notification arrival.\n  const d=line.match(/(\\d+)\\s*дн/iu),h=line.match(/(\\d+)\\s*год/iu),m=line.match(/(\\d+)\\s*хв/iu);\n  if(d||h||m) return received-((d?+d[1]*1440:0)+(h?+h[1]*60:0)+(m?+m[1]:0))*60000;\n  const time=line.match(/з\\s+(\\d{1,2}):(\\d{2})/iu);\n  if(time) {let t=new Date(received);t.setHours(+time[1],+time[2],0,0);if(t.getTime()>received)t.setDate(t.getDate()-1);return t.getTime();}\n  return received;\n}\nfunction record(next,at) {\n  // No historical baseline is invented from the previously tested widget status.\n  const last=history[history.length-1];\n  if(!last || last.status!==next) {\n    history.push({status:next,at});\n  } else if(next==='off' && at<last.at-120000) {\n    // A later factual report can move the start of the SAME ongoing outage backwards.\n    // Do not move it before an already recorded preceding ON event.\n    const prev=history[history.length-2];\n    last.at=Math.max(at,prev?prev.at+1000:at);\n  }\n  // Keep up to 90 days + last preceding state, so intervals across the cutoff remain calculable.\n  const cutoff=Date.now()-90*86400000;\n  const first=history.findIndex(e=>e.at>=cutoff);\n  if(first>1) history=history.slice(first-1);\n  fm.writeString(historyFile,JSON.stringify(history));\n}\nfunction update(next,start,received,hasReportedStart=false) {\n  const firstRecordedEvent=history.length===0;\n  const old=s.status;\n  const effectiveStart=next==='off'&&hasReportedStart ? start : received;\n  if(next!==old) {\n    if(old==='off'&&s.since) s.lastOutage=Math.max(0,received-s.since);\n    s.status=next;\n    s.since=next==='off'?effectiveStart:received;\n  } else if(firstRecordedEvent) {\n    // Previous status may have been created by manual tests. Start fresh on first REAL event.\n    s.since=effectiveStart;\n  } else if(next==='off'&&hasReportedStart&&(!s.since||effectiveStart<s.since-120000)) {\n    s.since=effectiveStart;\n  }\n  s.lastSeen=received;\n  record(next,effectiveStart);\n}\nfunction parseMessage(message) {\n  const received=Date.now();\n  const lines=message.replace(/\\r/g,'\\n').split('\\n').map(x=>x.trim());\n  // Switch announcements; each address list may wrap onto the next line.\n  for(let i=0;i<lines.length;i++) {\n    const match=lines[i].match(/(увімкнулось|вимкнулось)\\s*:/iu);\n    if(!match)continue;\n    let addresses=lines[i].slice(lines[i].indexOf(':')+1);\n    let j=i+1;\n    while(j<lines.length&&/^[,\\s#]*[РP][КKБBТT]/iu.test(lines[j].replace(/^[^\\p{L}#]*/u,''))) {\n      addresses+=' '+lines[j];j++;\n    }\n    if(rk10.test(addresses)) {\n      const on=match[1].toLowerCase()==='увімкнулось';\n      update(on?'on':'off',received,received,false);\n      return true;\n    }\n  }\n  if(/графік на|аварійні відключення|планові графіки/iu.test(message)\n     && !/не робе|поки робе/iu.test(message))return false;\n  for(const line of lines) {\n    if(!rk10.test(line))continue;\n    if(/нема(?:є)? світла|без світла|не робе/iu.test(line)) {\n      const hasTime=/\\d+\\s*(?:дн|год|хв)|з\\s+\\d{1,2}:\\d{2}/iu.test(line);\n      update('off',reportedStart(line,received),received,hasTime);return true;\n    }\n    if(/поки робе|поки працює|є світло|світло є/iu.test(line)) {\n      update('on',received,received,false);return true;\n    }\n  }\n  // Approved user-taught phrases; only on a line explicitly mentioning RK10.\n  for(const line of lines){\n    if(!rk10.test(line))continue;\n    const normalized=adNorm(line);\n    for(const rule of adRules('status')){\n      if(!rule||typeof rule.phrase!=='string'||rule.phrase.length<5)continue;\n      if(normalized.includes(adNorm(rule.phrase))){\n        update(rule.value,received,received,false);return true;\n      }\n    }\n    // Conservative dictionary of common alternative announcements.\n    const off=/знеструмлен|немає (?:електро)?живлення|відсутн[єя] електропостачання|електропостачання припинен|напруг[аи] відсутн|живлення відключено/iu;\n    const on=/електропостачання відновлен|подачу (?:електро)?енергії відновлен|електроживлення відновлен|напруг[ау] подано|заживлен|живлення відновлено/iu;\n    if(off.test(line) && !on.test(line)){update('off',received,received,false);return true;}\n    if(on.test(line) && !off.test(line)){update('on',received,received,false);return true;}\n  }\n  return false;\n}\n// Diagnostics: an alert only when an incoming message LOOKS like a status\n// for RK10 but none of the supported formats can be parsed.\nconst diagnosticFile=fm.joinPath(dir,'light-unrecognized.json');\nconst diagnosticLogFile=fm.joinPath(dir,'light-unrecognized-log.json');\nfunction probableStatusMessage(message) {\n  const t=String(message);\n  if(!rk10.test(t))return false;\n  // Published timetables are NOT real-time switch events.\n  if(/графік на|графік відключень|аварійні відключення|планові графіки/iu.test(t)\n    && !/увімкнулось\\s*:|вимкнулось\\s*:|немає світла|нема світла|поки робе|поки працює/iu.test(t))return false;\n  return /світл|електр|увімк|вимк|напруг|знеструм|живлен|не роб|працю|🔴|🟢|⚡|струм|енерг/iu.test(t);\n}\nfunction saveUnrecognized(raw) {\n  const received=Date.now();\n  const message=String(raw).slice(0,5000);\n  const item={at:received,message};\n  let log=[];\n  if(fm.fileExists(diagnosticLogFile)) {\n    try { const data=JSON.parse(fm.readString(diagnosticLogFile));if(Array.isArray(data))log=data; }catch(_){}\n  }\n  const same=log.length>0&&log[log.length-1].message===message&&received-log[log.length-1].at<30*60000;\n  if(!same) {\n    log.push(item);\n    fm.writeString(diagnosticLogFile,JSON.stringify(log.slice(-50)));\n  }\n  fm.writeString(diagnosticFile,JSON.stringify({at:received,message,warning:'Не розпізнано формат статусу РК10'}));\n  if(!same) {\n    // Local notification: best effort; requires notifications enabled for Scriptable.\n    try {\n      const n=new Notification();\n      n.title='⚠️ РК10: не розпізнано статус світла';\n      n.body='Перевір повідомлення Telegram. Статус світла НЕ змінено. Текст записано в light-unrecognized-log.json.';\n      n.sound='default';\n      // Do not block Shortcuts automation on notification permission problems.\n      n.schedule().catch(e=>console.log('Сповіщення Scriptable: '+e));\n    } catch(e) {console.log('Сповіщення Scriptable: '+e);}\n  }\n  return !same;\n}\nfunction statusText() {\n  if(s.status==='unknown') return 'Немає даних про світло';\n  const result=[s.status==='on'?'Є світло':'Немає світла'];\n  if(s.status==='off'&&s.since)result.push('Вже '+dur(Date.now()-s.since));\n  else if(s.lastOutage!=null)result.push('Не було '+dur(s.lastOutage));\n  if(s.since)result.push((s.status==='on'?'Відновлено ':'Вимкнено ')+clock(s.since));\n  if(s.lastSeen)result.push('Останнє повідомлення '+clock(s.lastSeen));\n  return result.join('\\n');\n}\n// API-only; old Telegram shortcut inputs are ignored, history stays untouched.\nconst input=null;\nif(input!==null&&input!==undefined&&String(input).trim()!=='') {\n  let warningOutput=null;\n  if(String(input).trim()!=='STATUS') {\n    const raw=String(input);\n    const recognized=parseMessage(raw);\n    // Preserve normal successful update behavior.\n    if(recognized) fm.writeString(stateFile,JSON.stringify(s));\n    else if(probableStatusMessage(raw)) {\n      adAlert('status',raw,'Не розпізнано статус світла');\n      warningOutput='⚠️ НЕ РОЗПІЗНАНО СТАТУС РК10. Перевір Telegram.\\n'+raw.slice(0,350);\n    }\n  }\n  Script.setShortcutOutput(warningOutput||statusText());\n  Script.complete();\n} else {\n  const w=new ListWidget();w.backgroundColor=new Color('#000000');w.setPadding(15,15,15,15);\n  const on=s.status==='on',off=s.status==='off';\n  const color=new Color(on?'#22C55E':off?'#EF4444':'#A3A3A3');\n  const row=w.addStack();row.centerAlignContent();\n  const sym=SFSymbol.named(on?'bolt.fill':'bolt.slash.fill');\n  const icon=row.addImage(sym.image);icon.imageSize=new Size(20,20);icon.tintColor=color;\n  row.addSpacer(9);\n  const name=row.addText('Світло вдома');name.font=Font.boldSystemFont(15);name.textColor=Color.white();name.lineLimit=1;name.minimumScaleFactor=0.75;\n  w.addSpacer(16);\n  const title=w.addText(on?'Є світло':off?'Немає світла':'Немає даних');\n  title.font=Font.boldSystemFont(off?20:24);title.textColor=color;title.lineLimit=1;title.minimumScaleFactor=0.7;\n  w.addSpacer(8);\n  let detail='Очікуємо повідомлення';\n  if(off&&s.since)detail='Вже '+dur(Date.now()-s.since);\n  else if(on&&s.lastOutage!==null)detail='Не було '+dur(s.lastOutage);\n  else if(on)detail='Світло працює';\n  const txt=w.addText(detail);txt.font=Font.systemFont(12);txt.textColor=Color.white();txt.lineLimit=1;txt.minimumScaleFactor=0.7;\n  w.addSpacer(5);\n  const foot=w.addText(s.since?(on?'Відновлено о ':'Вимкнено о ')+clock(s.since):'Статус невідомий');\n  foot.font=Font.systemFont(10);foot.textColor=new Color('#A3A3A3');foot.lineLimit=1;\n  if(s.lastSeen) {\n    w.addSpacer(3);const stale=Date.now()-s.lastSeen>3600000;\n    const last=w.addText((stale?'⚠ ':'')+'Дані: '+clock(s.lastSeen));\n    last.font=Font.systemFont(9);last.textColor=new Color(stale?'#FBBF24':'#A3A3A3');last.lineLimit=1;\n  }\n  w.refreshAfterDate=new Date(Date.now()+60000);\n  Script.setWidget(w);\n  if(config.runsInApp)await w.presentSmall();\n  Script.complete();\n}\n","Світло вдома - Lock.js":"try{await importModule('Республіка · API').sync();}catch(e){console.log('API: '+e);}\n// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: cyan; icon-glyph: magic;\n\nconst fm = FileManager.local();\nconst path = fm.joinPath(\n  fm.documentsDirectory(),\n  \"light-home-api-v2.json\"\n);\n\nlet s = {status:\"unknown\", since:null};\n\nif (fm.fileExists(path)) {\n  try {\n    s = {...s, ...JSON.parse(fm.readString(path))};\n  } catch(e) {}\n}\n\nconst w = new ListWidget();\nw.backgroundColor = new Color(\"#000000\");\nw.setPadding(2, 2, 2, 2);\n\nconst on = s.status === \"on\";\nconst off = s.status === \"off\";\n\nconst color = new Color(\n  on ? \"#22C55E\" : off ? \"#EF4444\" : \"#AAAAAA\"\n);\n\nconst header = w.addText(\"⚡ Світло вдома\");\nheader.font = Font.boldSystemFont(11);\nheader.textColor = Color.white();\nheader.lineLimit = 1;\nheader.minimumScaleFactor = 0.7;\n\nw.addSpacer(3);\n\nconst title = w.addText(\n  on ? \"Є світло\" :\n  off ? \"Немає світла\" : \"Немає даних\"\n);\ntitle.font = Font.boldSystemFont(14);\ntitle.textColor = color;\ntitle.lineLimit = 1;\n\nif (off && s.since) {\n  w.addSpacer(3);\n  const minutes = Math.max(0,\n    Math.floor((Date.now() - s.since) / 60000)\n  );\n  const h = Math.floor(minutes / 60);\n  const m = minutes % 60;\n\n  const duration = w.addText(\n    \"Вже \" + (h ? h + \" год \" : \"\") + m + \" хв\"\n  );\n  duration.font = Font.systemFont(10);\n  duration.textColor = Color.white();\n}\n\nw.refreshAfterDate = new Date(Date.now()+60000);\nScript.setWidget(w);\nScript.complete();\n","Імпорт графіка.js":"// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: red; icon-glyph: magic;\n// SCRIPTABLE: importer for both widgets.\n// RK10 power schedule: shared routines (embedded into each standalone script).\nconst FM = FileManager.local();\nconst fmAD=FM;\n\n// Shared RK10 adaptation data. All original files are retained.\nconst AD_PENDING=fmAD.joinPath(fmAD.documentsDirectory(),'rk10-adaptive-pending.json');\nconst AD_RULES=fmAD.joinPath(fmAD.documentsDirectory(),'rk10-adaptive-rules.json');\nconst AD_LOG=fmAD.joinPath(fmAD.documentsDirectory(),'rk10-adaptive-log.json');\nfunction adRead(path,fallback){try{const a=JSON.parse(fmAD.readString(path));return a&&typeof a==='object'?a:fallback;}catch(_){return fallback;}}\nfunction adWrite(path,data){fmAD.writeString(path,JSON.stringify(data,null,2));}\nfunction adNorm(s){return String(s||'').toLowerCase().replace(/[’‘`]/g,\"'\").replace(/[‐‑‒–—−]/g,'-').replace(/\\s+/g,' ').trim();}\nfunction adAlert(kind,message,reason){\n  let now=Date.now(), list=adRead(AD_PENDING,[]);if(!Array.isArray(list))list=[];\n  const norm=adNorm(message), key=kind+'|'+norm;\n  const last=list.find(x=>x.key===key&&now-x.at<30*60000);\n  if(last)return;\n  list.push({id:'p'+now+'-'+Math.floor(Math.random()*10000),key,kind,at:now,message:String(message).slice(0,6000),reason,status:'pending'});\n  adWrite(AD_PENDING,list.slice(-100));\n  let log=adRead(AD_LOG,[]);if(!Array.isArray(log))log=[];\n  log.push({at:now,kind,reason,preview:String(message).slice(0,500)});adWrite(AD_LOG,log.slice(-200));\n  try{let n=new Notification();n.title='⚠️ РК10 · Перевір повідомлення';n.body=reason+'. Відкрий «РК10 · Перевірка повідомлень».';n.sound='default';let p=n.schedule();if(p&&p.catch)p.catch(e=>console.log('Сповіщення: '+e));}catch(e){console.log('Сповіщення: '+e);}\n}\nfunction adRules(kind){let o=adRead(AD_RULES,{});return Array.isArray(o[kind])?o[kind]:[];}\n\nconst STORAGE = FM.joinPath(FM.documentsDirectory(), 'rk10-schedules-v1.json');\nconst ADDRESS = 'РК10';\nfunction pad(n){return String(n).padStart(2,'0');}\nfunction dayKey(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}\nfunction midnight(d){return new Date(d.getFullYear(),d.getMonth(),d.getDate());}\nfunction plusDays(d,n){let x=midnight(d);x.setDate(x.getDate()+n);return x;}\nfunction load(){try {let o=JSON.parse(FM.readString(STORAGE));return o&&typeof o==='object'?o:{schedules:{},incidents:[]};}catch(e){return {schedules:{},incidents:[]};}}\nfunction save(o){FM.writeString(STORAGE,JSON.stringify(o));}\nfunction asStr(x){if(x==null)return ''; if(typeof x==='string')return x;try{return JSON.stringify(x)}catch(e){return String(x)}}\nfunction getInput(){let p=(args.plainTexts||[]).map(asStr).filter(Boolean);if(!p.length&&args.shortcutParameter!=null)p.push(asStr(args.shortcutParameter));return p.join('\\n').trim();}\nfunction norm(s){return String(s||'').replace(/\\u00a0/g,' ').replace(/[‐‑‒–—−]/g,'-').replace(/\\r/g,'').replace(/[ \t]+/g,' ').trim();}\nfunction isRK10(s){return /(?:^|[^\\p{L}\\p{N}])(?:рк|pk|rk)\\s*10(?![\\p{L}\\p{N}\\/])/iu.test(s);}\nfunction groupHeading(line){\n  let s=norm(line).replace(/^[🔴🟢🟥🟩⚡✅\\s]+/u,'');\n  if(s.length>160 || /\\d{1,2}:\\d{2}|графік|аварі|світл|відключ|застосову|не діють|скасован|ремонт|початок|заверш|год\\./iu.test(s))return false;\n  return /(?:^|[^\\p{L}\\p{N}])(?:РК\\s*\\d+[АA]?|ТР\\s*\\d+[АA]?|БШ\\s*\\d+(?:\\/\\d+)?[АA]?|Т4А)(?!\\p{L})/iu.test(s);\n}\nfunction parseTime(s){let m=String(s).trim().match(/^(\\d{1,2})(?:(?:[:.])(\\d{2}))?$/);if(!m)return null;let h=+m[1],mi=+(m[2]||0);return h<=24&&mi<60&&(h!==24||mi===0)?h*60+mi:null;}\nfunction parseRanges(lines,i){\n let ranges=[];\n for(let j=i+1;j<lines.length;j++){\n   let z=norm(lines[j]);\n   if(groupHeading(z)||/зі світлом\\s*:/iu.test(z)||/⚡|аварі|графік на|графік оновлено/iu.test(z))break;\n   let m=z.match(/^\\s*([🟢🟥🟩🔴✅❌])\\s*(\\d{1,2}(?:[:.]\\d{2})?)\\s*(?:-|до)\\s*(\\d{1,2}(?:[:.]\\d{2})?)/u);\n   if(!m){if(ranges.length && z && !/^\\s*[|•\\-]/.test(z))break;continue;}\n   let a=parseTime(m[2]),b=parseTime(m[3]);\n   if(a==null||b==null||b<=a)break;\n   let on=/[🟢🟩✅]/u.test(m[1]);ranges.push({from:a,to:b,on});\n }\n if(!ranges.length)return null;\n // Only accept a full contiguous, explicit 00:00–24:00 schedule. Truncated notifications must not overwrite valid data.\n if(ranges[0].from!==0||ranges[ranges.length-1].to!==1440)return null;\n for(let k=1;k<ranges.length;k++)if(ranges[k].from!==ranges[k-1].to||ranges[k].on===ranges[k-1].on)return null;\n return ranges;\n}\nconst MONTHS={'січня':1,'лютого':2,'березня':3,'квітня':4,'травня':5,'червня':6,'липня':7,'серпня':8,'вересня':9,'жовтня':10,'листопада':11,'грудня':12};\nfunction readScheduleDate(t,received){\n let m=t.match(/(?:графік|розклад)\\s+на\\s+(сьогодні|завтра)\\s*,?\\s*(\\d{1,2})?\\s*([а-яіїєґ]+)/iu);\n if(!m){m=t.match(/(?:графік|розклад)\\s+на\\s+(сьогодні|завтра)/iu);if(!m)return null;}\n let base=midnight(received), chosen=plusDays(base,m[1].toLowerCase()==='завтра'?1:0);\n if(m[2]&&m[3]&&MONTHS[m[3].toLowerCase()]){\n   let month=MONTHS[m[3].toLowerCase()],day=+m[2];\n   let y=chosen.getFullYear(),d=new Date(y,month-1,day);\n   // Year rollover for end-of-December posts describing early January and vice versa.\n   if((d.getTime()-base.getTime())>180*864e5)d=new Date(y-1,month-1,day);\n   if((base.getTime()-d.getTime())>180*864e5)d=new Date(y+1,month-1,day);\n   if(d.getDate()!==day || d.getMonth()!==month-1)return null;\n   return dayKey(d);\n }\n return dayKey(chosen);\n}\nfunction findScheduleDate(text,received){return readScheduleDate(norm(text),received);}\nfunction parseSchedules(text,received){\n let starts=[...text.matchAll(/(?:🔄\\s*)?(?:📅\\s*)?(?:Графік|Розклад)\\s+на\\s+(?:сьогодні|завтра)/giu)].map(m=>m.index);let chunks=starts.map((at,i)=>text.slice(at,starts[i+1]||text.length));\n let result=[];\n for(let chunk of chunks){let date=findScheduleDate(chunk,received);if(!date)continue;\n let lines=chunk.split('\\n');\n for(let i=0;i<lines.length;i++){\n   if(!groupHeading(lines[i])||!isRK10(lines[i]))continue;\n   let ranges=parseRanges(lines,i);if(ranges)result.push({date,ranges});\n }\n }\n return result;\n}\nfunction incidentStatus(text){\n let s=norm(text);\n if(/аварій[а-яіїєґ]*\\s+відключенн[а-яіїєґ]*\\s+скасован|аварій[а-яіїєґ]*\\s+відключенн[а-яіїєґ]*\\s+завершен|планов[а-яіїєґ]*\\s+графік[а-яіїєґ]*\\s+(?:відновлен|діють)/iu.test(s))return 'cancel';\n if(/аварій[а-яіїєґ]*\\s+відключенн[а-яіїєґ]*|планов[а-яіїєґ]*\\s+графік[а-яіїєґ]*\\s+не\\s+діють/iu.test(s))return 'active';\n return '';\n}\nfunction getIncidentDays(text,received){\n let m=norm(text).match(/(?:графік\\s+на\\s+)?(сьогодні|завтра)\\s*,?\\s*(\\d{1,2})?\\s*([а-яіїєґ]+)?/iu);\n let d=m?readScheduleDate('Графік на '+m[0].replace(/^графік\\s+на\\s+/iu,''),received):null;\n let base=d?new Date(d+'T00:00:00'):midnight(received);\n let days=[dayKey(base)];\n // Specific cross-midnight outages marked with HH:MM–HH:MM.\n let spans=[...norm(text).matchAll(/(\\d{1,2}:\\d{2})\\s*-\\s*(\\d{1,2}:\\d{2})/gu)];\n if(spans.some(m=>{let a=parseTime(m[1]),b=parseTime(m[2]);return a!==null&&b!==null&&b<a&&b>0;}))days.push(dayKey(plusDays(base,1)));\n return [...new Set(days)];\n}\nfunction importText(text,received){\n const db=load();db.schedules=db.schedules||{};db.incidents=db.incidents||[];\n let changed=0,why=[];\n let schedules=parseSchedules(text,received);\n for(let s of schedules){\n   let old=db.schedules[s.date];\n   // Incoming latest matching message replaces earlier message for same date.\n   if(!old||old.received<=received.getTime()){\n     db.schedules[s.date]={ranges:s.ranges,received:received.getTime()};changed++;why.push('Графік '+s.date);\n   }\n }\n let state=incidentStatus(text);\n // An address-specific DTEK accident may be included at the end of an ordinary schedule message.\n if(!state && /⚡\\s*АВАРІЯ\\s*ДТЕК/iu.test(text)){let part=text.slice(text.search(/⚡\\s*АВАРІЯ\\s*ДТЕК/iu));if(isRK10(part))state='active';}\n if(state){\n   // Avoid an irrelevant house's incident affecting RK10, but allow globally announced warnings.\n   let hasAddress=/\\b(?:РК|ТР|БШ|Т4А)\\s*\\d/iu.test(text);\n   if(!hasAddress || isRK10(text)){\n     let days=getIncidentDays(text,received);\n     for(let d of days){\n       db.incidents=db.incidents.filter(x=>x.date!==d);\n       db.incidents.push({date:d,status:state,received:received.getTime()});changed++;\n     }\n     why.push(state==='active'?'Аварійний режим':'Аварію скасовано');\n   }\n }\n // Keep recent dates only.\n const cutoff=dayKey(plusDays(received,-10));\n for(let d of Object.keys(db.schedules))if(d<cutoff)delete db.schedules[d];\n db.incidents=db.incidents.filter(x=>x.date>=cutoff);\n if(changed)save(db);\n return {changed,why,schedules:schedules.length,incident:state};\n}\n\nfunction adCheckInput(text,result){\n  const t=adNorm(text);\n  if(!isRK10(t))return;\n  // \"Планові графіки не діють\" is an emergency notice, NOT a schedule.\n  // Only posts explicitly announcing a schedule for today/tomorrow qualify.\n  const scheduleHeader=/(?:графік|розклад)\\s+на\\s+(?:сьогодні|завтра)/iu.test(t);\n  const emergency=/(?:аварій[а-яіїєґ]*\\s+відключенн|аварі[яїієґ]|аварійн|планов[а-яіїєґ]*\\s+графік[а-яіїєґ]*\\s+не\\s+діють|⚡\\s*аварія\\s*дтек)/iu.test(t);\n  if(scheduleHeader && result.schedules===0){\n    adAlert('schedule',text,'Не вдалося прочитати повний плановий графік РК10');\n  } else if(emergency && !result.incident){\n    adAlert('incident',text,'Не вдалося визначити аварійне повідомлення РК10');\n  }\n}\n// Telegram notification trigger fires for every message from the ЖК channel.\n// A status message is handled by \"Світло вдома\", not by this schedule importer.\n// Skip all unrelated notifications BEFORE touching schedule files or opening dialogs.\nfunction isImporterMessage(text){\n const t=norm(text);\n const isSchedule=/(?:графік|розклад)\\s+на\\s+(?:сьогодні|завтра)/iu.test(t);\n const isIncident=/(?:аварійн[а-яіїєґ]*\\s+відключенн|аварі[яїієґ]|аварія\\s+дтек|планов[а-яіїєґ]*\\s+графік[а-яіїєґ]*\\s+не\\s+діють)/iu.test(t);\n return isSchedule || isIncident;\n}\nfunction importError(e,input){\n const msg=String(e && (e.stack||e.message)||e).slice(0,1500);\n try {\n   let log=adRead(AD_LOG,[]);if(!Array.isArray(log))log=[];\n   log.push({at:Date.now(),kind:'import_error',reason:msg,preview:String(input).slice(0,500)});\n   adWrite(AD_LOG,log.slice(-200));\n }catch(_){}\n try { adAlert('import_error',input,'Помилка імпорту графіка: '+msg.slice(0,130)); }catch(_){}\n console.log('РК10 імпорт: '+msg);\n}\nconst input=getInput();\ntry {\n if(config.runsWithSiri){\n   if(!input || !isImporterMessage(input)){\n     // Normal state switch (e.g. \"Увімкнулось: #РК10\") or unrelated ЖК post.\n     Script.setShortcutOutput('Пропущено: це не графік і не аварійне повідомлення');\n   }else{\n     const result=importText(input,new Date());\n     adCheckInput(input,result);\n     Script.setShortcutOutput(result.changed?'Збережено: '+result.why.join(', '):'Повного графіка РК10 в повідомленні немає');\n   }\n }else{\n   // Preserve the original interactive Scriptable mode for manual import.\nif(input){let r=importText(input,new Date());adCheckInput(input,r);{let a=new Alert();a.title=r.changed?'Дані оновлено':'Не імпортовано';a.message=r.changed?r.why.join('\\n'):'Перевір повний текст повідомлення та наявність РК10';a.addAction('ОК');await a.present();}}\nelse if(!config.runsInWidget){let a=new Alert();a.title='Імпорт графіка РК10';a.message='Скопіюй ПОВНЕ повідомлення з Telegram, потім натисни «Вставити». Автоматизація може також передавати Основний текст сповіщення в Texts.';a.addAction('Вставити');a.addCancelAction('Скасувати');if((await a.present())===0){let pasted=Pasteboard.pasteString();if(pasted){let r=importText(pasted,new Date());adCheckInput(pasted,r);let b=new Alert();b.title=r.changed?'Дані оновлено':'Немає повного графіка РК10';b.message=r.why.join('\\n')||'Скопійоване повідомлення неповне або не містить потрібного блоку.';b.addAction('Гаразд');await b.present();}}}\n }\n}catch(e){\n // Do not allow a parser/storage error to crash a Shortcuts notification automation.\n importError(e,input);\n if(config.runsWithSiri){try{Script.setShortcutOutput('Помилка імпорту записана в журнал РК10');}catch(_){}}\n else {const a=new Alert();a.title='Помилка імпорту';a.message=String(e);a.addAction('ОК');await a.present();}\n}\n\nScript.complete();\n","Графік сьогодні+завтра.js":"// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: teal; icon-glyph: magic;\n// РК10 · робочий Large-віджет. Геометрія = погоджений користувачем тест.\n// Дані: rk10-schedules-v1.json, заповнює скрипт «02_Імпорт_Telegram_РК10».\n// Віджет нічого не записує і не змінює інші віджети світла.\nconst C = {\n  bg: new Color('#080808'), white: new Color('#FFFFFF'),\n  muted: new Color('#A6A6AA'), gray: new Color('#707077'),\n  green: new Color('#69E38B'), red: new Color('#F17479'),\n  alert: new Color('#F58C94'), line: new Color('#55555A'),\n  gold: new Color('#FFD43B')\n};\nconst padding = 13;\nconst graphW = Device.screenSize().width - 48 - 2 * padding;\nconst graphH = 92;\nconst fm = FileManager.local();\nconst store = fm.joinPath(fm.documentsDirectory(), 'rk10-schedules-v1.json');\nfunction pad(n) { return String(n).padStart(2, '0'); }\nfunction key(d) { return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()); }\nfunction calendarDay(now, shift) { return new Date(now.getFullYear(), now.getMonth(), now.getDate()+shift); }\nfunction displayDate(d) { return 'РК10 · ' + pad(d.getDate()) + '.' + pad(d.getMonth()+1); }\nfunction readDB() {\n  try {\n    if (!fm.fileExists(store)) return { schedules:{}, incidents:[] };\n    let x = JSON.parse(fm.readString(store));\n    if (!x || typeof x !== 'object') throw Error('invalid storage');\n    return { schedules: x.schedules && typeof x.schedules==='object' ? x.schedules : {}, incidents:Array.isArray(x.incidents)?x.incidents:[] };\n  } catch (_) { return { schedules:{}, incidents:[] }; }\n}\nfunction validRanges(ranges) {\n  if (!Array.isArray(ranges) || !ranges.length || ranges[0].from !== 0 || ranges[ranges.length-1].to !== 1440) return false;\n  for (let i=0;i<ranges.length;i++) {\n    let s = ranges[i];\n    if (!Number.isInteger(s.from) || !Number.isInteger(s.to) || s.from<0 || s.to>1440 || s.to<=s.from || typeof s.on!=='boolean') return false;\n    if (i && (s.from!==ranges[i-1].to || s.on===ranges[i-1].on)) return false;\n  }\n  return true;\n}\nfunction hasIncident(db, date) {\n  let matches = db.incidents.filter(x => x && x.date===date && (x.status==='active'||x.status==='cancel'));\n  matches.sort((a,b)=>(b.received||0)-(a.received||0));\n  return matches.length>0 && matches[0].status==='active';\n}\nfunction text(parent, value, size, color, bold=false) {\n  const t=parent.addText(value);\n  t.font=bold?Font.boldSystemFont(size):Font.systemFont(size);\n  t.textColor=color;\n  t.lineLimit=1;\n  t.minimumScaleFactor=.95;\n  return t;\n}\nfunction header(w, title, date, sign) {\n  const row=w.addStack(); row.centerAlignContent();\n  text(row,sign,18,C.gold,true);row.addSpacer(6);\n  text(row,title,17.5,C.white,true);row.addSpacer();\n  text(row,date,10.5,C.muted);\n}\nfunction status(w, warning) {\n  const row=w.addStack();row.centerAlignContent();\n  text(row,warning?'⚠':'✓',16,warning?C.alert:C.green,true);row.addSpacer(7);\n  text(row,warning?'Аварійні відключення':'Аварій не повідомлено',13,warning?C.alert:C.green);\n}\nfunction fmt(minute) {\n  if(minute===1440)return '24:00';\n  return pad(Math.floor(minute/60))+':'+pad(minute%60);\n}\n// Exact graphic function from approved Large test.\nfunction segment(ctx,from,to,y,h,first,last,color) {\n  const x1=graphW*from/1440, x2=graphW*to/1440;\n  if(x2<=x1)return;\n  const r=Math.min(h/2,(x2-x1)/2),p=new Path();\n  p.move(new Point(x1+(first?r:0),y));\n  p.addLine(new Point(x2-(last?r:0),y));\n  if(last)p.addQuadCurve(new Point(x2,y+r),new Point(x2,y));\n  p.addLine(new Point(x2,y+h-(last?r:0)));\n  if(last)p.addQuadCurve(new Point(x2-r,y+h),new Point(x2,y+h));\n  p.addLine(new Point(x1+(first?r:0),y+h));\n  if(first)p.addQuadCurve(new Point(x1,y+h-r),new Point(x1,y+h));\n  p.addLine(new Point(x1,y+(first?r:0)));\n  if(first)p.addQuadCurve(new Point(x1+r,y),new Point(x1,y));\n  p.closeSubpath();ctx.addPath(p);ctx.setFillColor(color);ctx.fillPath();\n}\nfunction graph(ranges) {\n  const ctx=new DrawContext();ctx.size=new Size(graphW,graphH);ctx.respectScreenScale=true;ctx.opaque=false;\n  const barY=45,barH=22;\n  const data=ranges||[{from:0,to:1440,on:null}];\n  for(let i=0;i<data.length;i++){\n    const s=data[i];\n    segment(ctx,s.from,s.to,barY,barH,i===0,i===data.length-1,\n      s.on===null?C.gray:(s.on?C.green:C.red));\n  }\n  const marks=ranges?[0,...ranges.slice(0,-1).map(s=>s.to),1440]:[0,360,720,1080,1440];\n  const labelWidth=43;\n  const rows=[[],[],[{left:0,right:labelWidth},{left:graphW-labelWidth,right:graphW}]];\n  ctx.setFont(Font.systemFont(11.1));ctx.setTextColor(C.white);ctx.setTextAlignedCenter();\n  for(const minute of [...new Set(marks)].sort((a,b)=>a-b)){\n    const x=graphW*minute/1440,edge=minute===0||minute===1440;\n    const left=Math.max(0,Math.min(graphW-labelWidth,x-labelWidth/2));\n    const preferences=minute===810?[2,1,0]:[1,0,2];\n    let row=edge?2:-1;\n    if(!edge){\n      for(const candidate of preferences){\n        const free=rows[candidate].every(a=>left>=a.right+3||left+labelWidth<=a.left-3);\n        if(free){row=candidate;break;}\n      }\n      if(row<0)row=0;\n      rows[row].push({left,right:left+labelWidth});\n    }\n    const yy=[0,21,73][row];\n    ctx.drawTextInRect(fmt(minute),new Rect(left,yy,labelWidth,17));\n    ctx.setFillColor(C.muted);\n    const lineStart=row===2?barY+barH:(row===0?16:37);\n    const lineEnd=row===2?73:barY;\n    ctx.fillRect(new Rect(Math.max(0,x-.35),lineStart,.7,lineEnd-lineStart));\n  }\n  return ctx.getImage();\n}\nfunction chart(w,ranges){\n  const im=w.addImage(graph(ranges));im.imageSize=new Size(graphW,graphH);im.resizable=false;\n}\nfunction divider(w){\n  const ctx=new DrawContext();ctx.size=new Size(graphW,2);ctx.respectScreenScale=true;ctx.opaque=false;\n  ctx.setFillColor(C.line);ctx.fillRect(new Rect(0,0,graphW,1));\n  const im=w.addImage(ctx.getImage());im.imageSize=new Size(graphW,2);im.resizable=false;\n}\n// Only dynamic data and dates differ from the approved test.\nconst now=new Date(),today=calendarDay(now,0),tomorrow=calendarDay(now,1);\nconst db=readDB();\nconst a=db.schedules[key(today)],b=db.schedules[key(tomorrow)];\nconst todayRanges=a&&validRanges(a.ranges)?a.ranges:null;\nconst tomorrowRanges=b&&validRanges(b.ranges)?b.ranges:null;\nconst todayAlert=hasIncident(db,key(today)),tomorrowAlert=hasIncident(db,key(tomorrow));\nconst w=new ListWidget();w.backgroundColor=C.bg;w.setPadding(12,padding,11,padding);\nheader(w,'Графік на сьогодні',displayDate(today),'⚡');\nw.addSpacer(7);status(w,todayAlert);w.addSpacer(3);chart(w,todayRanges);w.addSpacer(2);\ntext(w,todayAlert?'Плановий графік може не діяти':(todayRanges?'За повідомленням ЖК':'Очікуємо графік на сьогодні'),12,todayAlert?C.alert:C.muted);\nw.addSpacer(13);divider(w);w.addSpacer(13);\nheader(w,'Графік на завтра',displayDate(tomorrow),'▦');\nw.addSpacer(7);status(w,tomorrowAlert);w.addSpacer(3);chart(w,tomorrowRanges);w.addSpacer(3);\ntext(w,tomorrowAlert?'Плановий графік може не діяти':(tomorrowRanges?'За повідомленням ЖК':'Очікуємо графік на завтра'),12,tomorrowAlert?C.alert:C.muted);\nScript.setWidget(w);if(!config.runsInWidget)await w.presentLarge();Script.complete();\n","План vs Факт.js":"try{await importModule('Республіка · API').sync();}catch(e){console.log('API: '+e);}\n// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: red; icon-glyph: magic;\n// РК10 · План vs Факт — LARGE, компактна версія з читабельними підписами\n// Лише читає rk10-schedules-v1.json та light-history-api-v2.json.\n// Не змінює графіки, історію чи інші віджети.\nconst fm = FileManager.local();\nconst root = fm.documentsDirectory();\nconst now = Date.now();\nconst PLAN = fm.joinPath(root, 'rk10-schedules-v1.json');\nconst FACT = fm.joinPath(root, 'light-history-api-v2.json');\nconst colors = {bg:'#090909', white:'#FFFFFF', muted:'#A3A3A3',green:'#4ADE80',red:'#F87171',yellow:'#EAB308',line:'#444444',tile:'#181818',gray:'#303030'};\nconst color = x => new Color(colors[x] || x);\nfunction load(file) {try {return fm.fileExists(file) ? JSON.parse(fm.readString(file)) : null;} catch(e) {console.log('Помилка JSON: '+e);return null;}}\nfunction pad(n) {return String(n).padStart(2,'0');}\nfunction key(d) {return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;}\nfunction dayStart(d){return new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();}\nfunction addDay(d,n){const a = new Date(dayStart(d));a.setDate(a.getDate()+n);return a;}\nfunction hm(ts){const d=new Date(ts);return `${pad(d.getHours())}:${pad(d.getMinutes())}`;}\nfunction duration(ms){const m=Math.floor(Math.max(0,ms)/60000);return m>=60 ? `${Math.floor(m/60)} год ${m%60} хв` : `${m} хв`;}\nfunction shortDuration(ms){const m=Math.floor(Math.max(0,ms)/60000);return m>=60 ? `${Math.floor(m/60)} год ${m%60} хв` : `${m} хв`;}\nfunction validRanges(a){if(!Array.isArray(a)||!a.length||a[0].from!==0||a[a.length-1].to!==1440)return false;\n  return a.every((r,i)=>Number.isInteger(r.from)&&Number.isInteger(r.to)&&r.to>r.from&&r.from>=0&&r.to<=1440&&typeof r.on==='boolean'&&(!i||(r.from===a[i-1].to&&r.on!==a[i-1].on)));}\n// Data-quality monitor: read-only, no modifications to source files.\nfunction warnData(reason){\n const p=fm.joinPath(root,'rk10-plan-fact-data-warnings.json');let x={};try{x=JSON.parse(fm.readString(p))}catch(_){}\n const t=Date.now(),key=reason;if(t-(x[key]||0)<24*3600000)return;\n x[key]=t;fm.writeString(p,JSON.stringify(x));\n try{let n=new Notification();n.title='⚠️ РК10 · Помилка статистики';n.body=reason+' · Дані не змінено.';let v=n.schedule();if(v&&v.catch)v.catch(e=>console.log(String(e)));}catch(e){console.log(String(e));}\n}\nconst db = load(PLAN);const history = load(FACT);\nconst schedules = db && db.schedules && typeof db.schedules==='object' ? db.schedules : {};\nif(fm.fileExists(PLAN) && (!db || typeof db!=='object'||!db.schedules||typeof db.schedules!=='object'))warnData('Пошкоджено файл графіків');\nif(fm.fileExists(FACT) && !Array.isArray(history))warnData('Пошкоджено історію світла');\nif(db && db.schedules && Object.values(db.schedules).some(v=>v&&!validRanges(v.ranges)))warnData('Некоректні інтервали графіка');\nif(Array.isArray(history) && history.some(e=>!e||!['on','off'].includes(e.status)||!Number.isFinite(e.at)))warnData('Некоректні події в історії');\nconst rawEvents = Array.isArray(history) ? history : [];\nconst events = rawEvents.filter(e=>e&&(e.status==='on'||e.status==='off')&&Number.isFinite(e.at)&&e.at<=now)\n .map(e=>({at:e.at,on:e.status==='on'})).sort((a,b)=>a.at-b.at);\n// Для дублікатів одного часу беремо останню подію.\nconst unique=[];for(const ev of events){if(unique.length&&unique[unique.length-1].at===ev.at)unique[unique.length-1]=ev;else unique.push(ev);}\n// Pair across midnight, assigning each planned/factual transition at most once.\nconst plannedChanges=[];\nfor(const dateKey of Object.keys(schedules).sort()){\n const day=schedules[dateKey];if(!day||!validRanges(day.ranges)||!/^(\\d{4})-(\\d{2})-(\\d{2})$/.test(dateKey))continue;\n const [yy,mm,dd]=dateKey.split('-').map(Number),date=new Date(yy,mm-1,dd),base=dayStart(date);\n if(key(date)!==dateKey)continue;\n for(let i=1;i<day.ranges.length;i++)plannedChanges.push({at:base+day.ranges[i].from*60000,on:day.ranges[i].on});\n const prev=schedules[key(addDay(date,-1))];\n if(prev&&validRanges(prev.ranges)&&prev.ranges[prev.ranges.length-1].on!==day.ranges[0].on)plannedChanges.push({at:base,on:day.ranges[0].on});\n}\nplannedChanges.sort((a,b)=>a.at-b.at);\nconst choices=[];\nfor(let i=0;i<unique.length;i++)for(let j=0;j<plannedChanges.length;j++){\n const a=unique[i],p=plannedChanges[j],gap=Math.abs(a.at-p.at);\n if(a.on===p.on&&gap<=3*3600000)choices.push({i,j,gap});\n}\nchoices.sort((a,b)=>a.gap-b.gap||unique[a.i].at-unique[b.i].at);\nconst usedF=new Set(),usedP=new Set(),pairedByFact=new Map();\nfor(const c of choices){\n if(usedF.has(c.i)||usedP.has(c.j))continue;\n usedF.add(c.i);usedP.add(c.j);\n const a=unique[c.i],p=plannedChanges[c.j];\n pairedByFact.set(c.i,{at:a.at,planned:p.at,on:a.on,delta:Math.round((a.at-p.at)/60000)});\n}\nfunction compare(date){\n const start=dayStart(date),end=Math.min(dayStart(addDay(date,1)),now),s=schedules[key(date)];\n if(end<=start||!s||!validRanges(s.ranges))return null;\n const plans=s.ranges.map(r=>({a:new Date(date.getFullYear(),date.getMonth(),date.getDate(),0,r.from).getTime(),b:new Date(date.getFullYear(),date.getMonth(),date.getDate(),0,r.to).getTime(),on:r.on}));\n const facts=[];\n for(let i=0;i<unique.length;i++){const a=Math.max(start,unique[i].at),b=Math.min(end,i+1<unique.length?unique[i+1].at:now);if(b>a)facts.push({a,b,on:unique[i].on});}\n let covered=0,match=0,extra=0,missed=0;\n for(const f of facts)for(const p of plans){const a=Math.max(f.a,p.a,start),b=Math.min(f.b,p.b,end);if(b<=a)continue;const span=b-a;covered+=span;if(p.on===f.on)match+=span;else if(f.on)extra+=span;else missed+=span;}\n const pairs=[],unmatched=[];\n for(let i=0;i<unique.length;i++){const e=unique[i];if(e.at<start||e.at>=end)continue;if(pairedByFact.has(i))pairs.push(pairedByFact.get(i));else unmatched.push(e);}\n return {date,start,end,covered,match,extra,missed,pairs,unmatched,accuracy:covered?Math.round(match/covered*100):null,coverage:Math.round(covered/(end-start)*100)};\n}\nconst today=new Date();const series=[];for(let i=6;i>=0;i--){const d=addDay(today,-i);series.push({date:d,day:['Нд','Пн','Вт','Ср','Чт','Пт','Сб'][d.getDay()],data:compare(d)});}\nconst available=series.filter(s=>s.data&&s.data.covered>0);\nconst selected=available.length?available[available.length-1].data:null;\nconst ranked=selected?[...selected.pairs].sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)||a.planned-b.planned):[];\nconst recent=ranked.slice(0,2);\nconst more=Math.max(0,ranked.length-2);\n\n\n// UI: компактний Large — точність + баланс, два відхилення, 7 днів.\nfunction UIcolor(v){return new Color(({bg:'#090909',white:'#FFFFFF',muted:'#A3A3A3',green:'#4ADE80',red:'#F87171',yellow:'#EAB308',gray:'#303030',tile:'#1B1B1B',line:'#444444'})[v]||v);}\nfunction textUI(p,value,size=12,tone='white',bold=false){let t=p.addText(String(value));t.font=bold?Font.boldSystemFont(size):Font.systemFont(size);t.textColor=UIcolor(tone);t.lineLimit=1;t.minimumScaleFactor=0.77;return t;}\nfunction hrow(p){let s=p.addStack();s.layoutHorizontally();s.centerAlignContent();return s;}\nfunction space(p,n){p.addSpacer(n);}\nfunction rule(p,width){let d=p.addStack();d.size=new Size(width,1);d.backgroundColor=UIcolor('line');}\nfunction balanceMs(v){if(v===null)return '—';const m=Math.round(Math.abs(v)/60000),sign=v<0?'−':v>0?'+':'';return sign+(m>=60?Math.floor(m/60)+' год '+m%60+' хв':m+' хв');}\nfunction balSmall(ms){if(ms===null)return '—';const m=Math.round(Math.abs(ms)/60000);return (ms>0?'+':ms<0?'−':'')+(m>=60?Math.floor(m/60)+':'+pad(m%60):m+'хв');}\nfunction balanceTone(ms){return ms>0?'green':ms<0?'red':'white';}\nfunction pctTone(accuracy){return accuracy===null?'white':accuracy>=85?'green':accuracy>=70?'yellow':'red';}\nconst chosenBalance=selected?selected.extra-selected.missed:null;\nconst screenW=Device.screenSize().width,innerW=screenW-48-28;\nconst widget=new ListWidget();widget.backgroundColor=UIcolor('bg');widget.setPadding(11,14,10,14);\nconst heading=hrow(widget);textUI(heading,'◫',16,'yellow',true);heading.addSpacer(6);textUI(heading,'План vs Факт',17,'white',true);heading.addSpacer();textUI(heading,selected?`РК10 · ${pad(selected.date.getDate())}.${pad(selected.date.getMonth()+1)}`:'РК10 · 7 днів',10.5,'muted');\nspace(widget,8);\nconst top=hrow(widget);const upperTileW=(innerW-8)/2;\nfunction statTile(parent,title,value,tone,note){let st=parent.addStack();st.layoutVertically();st.size=new Size(upperTileW,0);st.backgroundColor=UIcolor('tile');st.cornerRadius=10;st.setPadding(8,8,7,8);textUI(st,title,11,'muted');space(st,3);textUI(st,value,20,tone,true);space(st,2);textUI(st,note,9.5,'muted');return st;}\nstatTile(top,'Баланс світла',balanceMs(chosenBalance),chosenBalance===null?'white':balanceTone(chosenBalance),'за підтверджений час');top.addSpacer(8);\nstatTile(top,'Точність графіка',selected?selected.accuracy+'%':'—',selected?pctTone(selected.accuracy):'white','збіг плану й факту');\nspace(widget,7);\nconst totals=hrow(widget);\nfunction miniTile(parent,label,v,tone){let st=parent.addStack();st.layoutVertically();st.size=new Size(upperTileW,0);st.backgroundColor=UIcolor('tile');st.cornerRadius=9;st.setPadding(6,8,6,8);textUI(st,label,10.5,'muted');space(st,2);textUI(st,selected?(tone==='green'?'+':'−')+shortDuration(v):'—',13,tone,true);return st;}\nminiTile(totals,'⊕ Додаткове світло',selected?selected.extra:0,'green');totals.addSpacer(8);miniTile(totals,'⊖ Недоотримане',selected?selected.missed:0,'red');\nspace(widget,8);rule(widget,innerW);space(widget,7);\nconst deviations=hrow(widget);textUI(deviations,'Відхилення перемикань',12,'white',true);deviations.addSpacer();textUI(deviations,selected?(more?'Ще '+more+' · натисни':'Натисни'):'Немає даних',10.5,'muted');space(widget,5);\nfor(let i=0;i<2;i++){let p=recent[i];let r=hrow(widget);textUI(r,p?(p.on?'Увімкнення':'Вимкнення')+' о '+hm(p.planned):'—',11,p?'white':'muted');r.addSpacer();let good=p&&((p.on&&p.delta<0)||(!p.on&&p.delta>0));textUI(r,p?(p.delta===0?'вчасно':(p.delta<0?'−':'+')+Math.abs(p.delta)+' хв'):'—',11,p?(p.delta===0||good?'green':'red'):'muted',true);if(i===0)space(widget,3);}\nspace(widget,8);rule(widget,innerW);space(widget,7);\nconst weekly=hrow(widget);textUI(weekly,'Останні 7 днів',12,'white',true);weekly.addSpacer();textUI(weekly,'Точність / баланс',10.5,'muted');space(widget,6);\nconst bars=hrow(widget),barGap=4,cellW=Math.floor((innerW-6*barGap)/7),barH=44;\nfor(let i=0;i<series.length;i++){\n const d=series[i],a=d.data&&d.data.covered>0?d.data:null;\n const cell=bars.addStack();cell.layoutVertically();cell.size=new Size(cellW,77);\n const label=textUI(cell,d.day,10,'muted');label.centerAlignText();space(cell,3);\n let area=cell.addStack();area.layoutVertically();area.size=new Size(cellW,barH);\n area.backgroundColor=UIcolor('gray');area.cornerRadius=4;\n if(a){const fillHeight=Math.max(4,barH*a.accuracy/100);area.addSpacer(barH-fillHeight);\n const fill=area.addStack();fill.layoutVertically();fill.size=new Size(cellW,fillHeight);fill.cornerRadius=4;fill.backgroundColor=UIcolor(balanceTone(a.extra-a.missed));\n // Баланс пишемо всередині кольорового стовпчика, якщо вміщається.\n if(fillHeight>=15){fill.addSpacer();const centered=fill.addStack();centered.layoutHorizontally();centered.size=new Size(cellW,12);centered.addSpacer();let n=textUI(centered,balSmall(a.extra-a.missed),8,(a.extra-a.missed)>0?'#101418':'white',true);n.lineLimit=1;n.minimumScaleFactor=0.75;centered.addSpacer();fill.addSpacer();}}\n space(cell,3);const pctRow=cell.addStack();pctRow.layoutHorizontally();pctRow.size=new Size(cellW,12);pctRow.addSpacer();const percent=textUI(pctRow,a?a.accuracy+'%':'—',10,'white');percent.lineLimit=1;pctRow.addSpacer();\n if(i<series.length-1)bars.addSpacer(barGap);\n}\nspace(widget,5);textUI(widget,selected?'Перевірено: '+duration(selected.covered)+' із 24 год':'Очікуємо план та історію перемикань',10.5,'muted');\nwidget.url='scriptable:///run?scriptName='+encodeURIComponent(Script.name());\nScript.setWidget(widget);\n\nfunction escapeHTML(x){return String(x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));}\nfunction fullDayHTML(item){const d=item.data;\n const label=`${pad(item.date.getDate())}.${pad(item.date.getMonth()+1)}.${item.date.getFullYear()}`;\n if(!d||!d.covered)return `<section><h2>${label}</h2><p class=\"muted\">Немає спільних підтверджених даних плану й факту.</p></section>`;\n let list=[...d.pairs].sort((a,b)=>a.planned-b.planned);\n let events=list.map(p=>{const good=p.delta===0||(p.on&&p.delta<0)||(!p.on&&p.delta>0);\n return `<div class=\"event\"><div>${p.on?'Увімкнення':'Вимкнення'} <b>${hm(p.planned)}</b><small>Фактично: ${hm(p.at)}</small></div><b class=\"${good?'green':'red'}\">${p.delta===0?'вчасно':(p.delta<0?'раніше':'пізніше')+' на '+Math.abs(p.delta)+' хв'}</b></div>`;}).join('');\n if(!events)events='<p class=\"muted\">Підтверджених пар перемикань немає.</p>';\n if(d.unmatched.length)events+='<h3>Позапланові перемикання</h3>'+d.unmatched.map(e=>`<div class=\"event\">${e.on?'Позапланове ввімкнення':'Позапланове вимкнення'} ${hm(e.at)}</div>`).join('');\n return `<section><h2>${label}</h2>${cardHTML({accuracy:d.accuracy,extra:d.extra,missed:d.missed,covered:d.covered})}<h3>Усі перемикання (${list.length})</h3>${events}<p class=\"muted\">Відхилення перемикань — лише підтверджені пари. Баланс враховує всі підтверджені хвилини.</p></section>`;\n}\nfunction monthDate(anchor,offset){return new Date(anchor.getFullYear(),anchor.getMonth()+offset,1);}\nfunction summaryFor(items){let covered=0,match=0,extra=0,missed=0,elapsed=0,plannedDays=0,observedDays=0;\n for(let item of items){const d=item.data;if(!d)continue;plannedDays++;if(d.covered)observedDays++;covered+=d.covered;match+=d.match;extra+=d.extra;missed+=d.missed;elapsed+=Math.max(0,d.end-d.start);}\n return {covered,match,extra,missed,elapsed,plannedDays,observedDays,accuracy:covered?Math.round(100*match/covered):null};}\nfunction compactDay(item){let d=item.data;return {date:key(item.date),day:item.date.getDate(),weekday:item.date.getDay(),covered:d?d.covered:0,accuracy:d&&d.covered?d.accuracy:null,balance:d&&d.covered?d.extra-d.missed:null,html:fullDayHTML(item)};}\nfunction reportMonth(date){let first=new Date(date.getFullYear(),date.getMonth(),1),total=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),days=[];\n for(let i=1;i<=total;i++){let d=new Date(first.getFullYear(),first.getMonth(),i);days.push({date:d,data:compare(d)});}\n return {id:key(first),title:first.toLocaleDateString('uk-UA',{month:'long',year:'numeric'}),days:days.map(compactDay),summary:summaryFor(days)};}\nfunction cardHTML(s){if(!s||!s.covered)return '<p class=\"muted\">Недостатньо даних для підрахунку.</p>';\n let bal=s.extra-s.missed;\n return `<div class=\"stats\"><div><small>Баланс світла</small><strong class=\"${bal>0?'green':bal<0?'red':''}\">${bal>0?'+':bal<0?'−':'±'}${duration(Math.abs(bal))}</strong></div><div><small>Точність графіка</small><strong>${s.accuracy}%</strong></div><div><small>Додаткове світло</small><strong class=\"green\">+${duration(s.extra)}</strong></div><div><small>Недоотримане</small><strong class=\"red\">−${duration(s.missed)}</strong></div></div><p class=\"fine\">Перевірено: ${duration(s.covered)}. Невідомі періоди не враховано.</p>`;}\nasync function showReport(){let months=[];for(let i=-11;i<=0;i++)months.push(reportMonth(monthDate(today,i)));\n let all={months,week:series.map(compactDay),weekSummary:summaryFor(series),today:key(today)};\n let safe=JSON.stringify(all).replace(/</g,'\\\\u003c').replace(/&/g,'\\\\u0026');\n const html=`<!doctype html><html lang=\"uk\"><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta charset=\"utf-8\"><style>\n :root{color-scheme:dark}*{box-sizing:border-box}body{font:-apple-system-body;background:#090909;color:#fff;margin:0;padding:18px 15px 44px;font-family:-apple-system,BlinkMacSystemFont,sans-serif}h1{font-size:23px;margin:0 0 13px}h2{font-size:19px;margin:3px 0 14px}h3{font-size:16px;margin:18px 0 9px}small,.muted{color:#a3a3a3;font-size:13px}section{margin-top:13px;background:#151515;border:1px solid #343434;border-radius:16px;padding:14px}.stats{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}.stats>div{background:#252525;padding:11px 9px;border-radius:11px;min-width:0}.stats strong{font-size:20px;display:block;margin-top:6px;overflow-wrap:anywhere}.green{color:#4ade80!important}.red{color:#f87171!important}.fine{font-size:12px;color:#aaa;line-height:1.5}.event{border-top:1px solid #383838;display:flex;justify-content:space-between;align-items:flex-start;gap:9px;padding:12px 0;font-size:14px}.event b{font-size:13px}.event small{display:block;margin-top:3px}.tabs{background:#292929;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:4px;border-radius:12px}.tab{background:transparent;color:#aaa;border:0;border-radius:9px;padding:10px 0;font-size:14px}.tab.active{background:#575757;color:white;font-weight:700}.hidden{display:none}.nav{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:14px 0 8px}.nav button{background:#292929;color:#fff;border:0;border-radius:8px;min-width:34px;height:34px;font-size:23px}.nav button:disabled{opacity:.3}.nav strong{font-size:17px;text-transform:capitalize}.bars{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;margin:14px 0 6px}.column{text-align:center;min-width:0;font-size:11px;color:#aaa}.outer{height:92px;background:#292929;position:relative;border-radius:6px;margin:7px 0;overflow:hidden}.fill{position:absolute;bottom:0;width:100%;border-radius:5px;display:flex;align-items:flex-end;justify-content:center;padding-bottom:5px}.fill.pos{background:#26794d}.fill.neg{background:#a33f46}.fill.zero{background:#555}.inside{color:white;font-size:10px;font-weight:700;white-space:nowrap}.pct{font-weight:700;color:white;font-size:11px}.dayrow{display:grid;grid-template-columns:62px minmax(0,1fr) 38px 92px;gap:6px;padding:9px 0;border-bottom:1px solid #303030;align-items:center;font-size:12px}.track{height:9px;background:#363636;border-radius:8px;overflow:hidden}.track div{height:100%;background:#4ade80;border-radius:8px}.money{text-align:right;font-size:11px;font-weight:600}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.weekdays{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;color:#aaa;font-size:11px;margin:12px 0 7px}.calday{background:#292929;border:0;border-radius:8px;min-height:55px;color:#ddd;font-size:12px;padding:4px 2px;display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center}.calday .bal{font-size:9px;font-weight:700}.calday.pos{background:#173b28}.calday.neg{background:#442528}.calday.zero{background:#333}.calday:active{outline:1px solid white}.summarycard{margin-top:13px}.tip{border-radius:11px;background:#202820;color:#cdd8ce;padding:11px;font-size:12px;line-height:1.5;margin-top:12px}\n </style></head><body><h1>План vs Факт · РК10</h1><div class=\"tabs\"><button class=\"tab active\" data-v=\"day\">День</button><button class=\"tab\" data-v=\"week\">Тиждень</button><button class=\"tab\" data-v=\"month\">Місяць</button></div>\n <div id=\"day\"><div class=\"nav\"><button id=\"dayPrev\">‹</button><strong id=\"dayTitle\"></strong><button id=\"dayNext\">›</button></div><div id=\"dayBody\"></div></div>\n <div id=\"week\" class=\"hidden\"><section><h2>Останні 7 днів</h2><div id=\"weekStats\"></div><h3>Точність (%) і баланс (год:хв)</h3><div id=\"weekChart\"></div><h3>Деталізація за днями</h3><div id=\"weekRows\"></div></section></div>\n <div id=\"month\" class=\"hidden\"><section><div class=\"nav\"><button id=\"monthPrev\">‹</button><strong id=\"monthTitle\"></strong><button id=\"monthNext\">›</button></div><div id=\"monthStats\"></div><div class=\"nav\"><h3>Календар</h3></div><div class=\"weekdays\"><span>Пн</span><span>Вт</span><span>Ср</span><span>Чт</span><span>Пт</span><span>Сб</span><span>Нд</span></div><div class=\"calendar\" id=\"calendar\"></div></section></div>\n <script>const DATA=${safe};const $=id=>document.getElementById(id);const days=DATA.months.flatMap(m=>m.days),byDate=Object.fromEntries(days.map(d=>[d.date,d]));let dayKey=DATA.today,monthIndex=DATA.months.length-1;\n function dur(ms){const m=Math.round(Math.abs(ms)/60000);return m>=60?Math.floor(m/60)+' год '+(m%60)+' хв':m+' хв'}\n function signed(ms){if(ms==null)return '—';return (ms<0?'−':ms>0?'+':'')+dur(ms)}\n function short(ms){if(ms==null)return '—';const m=Math.round(Math.abs(ms)/60000);return (ms<0?'−':ms>0?'+':'')+(m>=60?Math.floor(m/60)+':'+String(m%60).padStart(2,'0'):m+'хв')}\n function dayLabel(v){const a=v.split('-');return a[2]+'.'+a[1]+'.'+a[0]}\n function setTab(v){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.v===v));['day','week','month'].forEach(x=>$(x).classList.toggle('hidden',x!==v));if(v==='day')drawDay();if(v==='week')drawWeek();if(v==='month')drawMonth()}\n document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setTab(b.dataset.v));\n function drawDay(){const i=days.findIndex(x=>x.date===dayKey);$('dayTitle').textContent=dayLabel(dayKey);$('dayBody').innerHTML=byDate[dayKey]?byDate[dayKey].html:'<section>Немає даних</section>';$('dayPrev').disabled=i<=0;$('dayNext').disabled=i<0||i>=days.length-1}\n $('dayPrev').onclick=()=>{let i=days.findIndex(x=>x.date===dayKey);if(i>0){dayKey=days[i-1].date;drawDay()}};\n $('dayNext').onclick=()=>{let i=days.findIndex(x=>x.date===dayKey);if(i>=0&&i<days.length-1){dayKey=days[i+1].date;drawDay()}};\n function selectDay(key){dayKey=key;setTab('day')}\n function cards(s){if(!s||!s.covered)return '<p class=\"muted\">Недостатньо підтверджених даних</p>';const b=s.extra-s.missed;return '<div class=\"stats\"><div><small>Баланс світла</small><strong class=\"'+(b>0?'green':b<0?'red':'')+'\">'+signed(b)+'</strong></div><div><small>Точність графіка</small><strong>'+s.accuracy+'%</strong></div><div><small>Додаткове світло</small><strong class=\"green\">+'+dur(s.extra)+'</strong></div><div><small>Недоотримане</small><strong class=\"red\">−'+dur(s.missed)+'</strong></div></div><div class=\"tip\">Баланс = додаткове світло − недоотримане. Рахується лише за підтвердженими періодами.</div><p class=\"fine\">Перевірено: '+dur(s.covered)+' · Днів із фактом: '+s.observedDays+'</p>'}\n function columns(list){return '<div class=\"bars\">'+list.map(d=>{const v=d.accuracy,ms=d.balance;return '<div class=\"column\"><div>'+['Нд','Пн','Вт','Ср','Чт','Пт','Сб'][d.weekday]+'</div><div class=\"outer\">'+(v==null?'':'<div class=\"fill '+(ms>0?'pos':ms<0?'neg':'zero')+'\" style=\"height:'+Math.max(4,v)+'%\"><span class=\"inside\">'+short(ms)+'</span></div>')+'</div><div class=\"pct\">'+(v==null?'—':v+'%')+'</div></div>'}).join('')+'</div>'}\n function rows(list){return list.map(d=>'<div class=\"dayrow\"><span>'+dayLabel(d.date).slice(0,5)+'</span><div class=\"track\"><div style=\"width:'+(d.accuracy==null?0:d.accuracy)+'%\"></div></div><b>'+(d.accuracy==null?'—':d.accuracy+'%')+'</b><b class=\"money '+(d.balance>0?'green':d.balance<0?'red':'')+'\">'+short(d.balance)+'</b></div>').join('')}\n function drawWeek(){$('weekStats').innerHTML=cards(DATA.weekSummary);$('weekChart').innerHTML=columns(DATA.week);$('weekRows').innerHTML=rows(DATA.week);$('weekRows').querySelectorAll('.dayrow').forEach((el,i)=>el.onclick=()=>selectDay(DATA.week[i].date))}\n function drawMonth(){const m=DATA.months[monthIndex];$('monthTitle').textContent=m.title;$('monthStats').innerHTML=cards(m.summary);$('monthPrev').disabled=monthIndex===0;$('monthNext').disabled=monthIndex>=DATA.months.length-1;\n const target=$('calendar');target.innerHTML='';const empty=(m.days[0].weekday+6)%7;for(let i=0;i<empty;i++)target.appendChild(document.createElement('div'));\n m.days.forEach(d=>{let el=document.createElement('button');el.className='calday '+(d.balance==null?'':d.balance>0?'pos':d.balance<0?'neg':'zero');el.innerHTML='<span>'+d.day+'</span><b>'+(d.accuracy==null?'—':d.accuracy+'%')+'</b><span class=\"bal\">'+short(d.balance)+'</span>';el.onclick=()=>selectDay(d.date);target.appendChild(el)});}\n $('monthPrev').onclick=()=>{if(monthIndex>0){monthIndex--;drawMonth()}};$('monthNext').onclick=()=>{if(monthIndex<DATA.months.length-1){monthIndex++;drawMonth()}};\n drawDay();</script></body></html>`;\n const web=new WebView();await web.loadHTML(html);await web.present();\n}\nif(!config.runsInWidget)await showReport();\nScript.complete();\n","Перевірка повідомлень.js":"// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: red; icon-glyph: magic;\n// Scriptable — RK10 adaptation inbox and safe, confirmed learning.\n// Run manually in the Scriptable app. Does not rewrite any existing script.\nconst fm=FileManager.local(),dir=fm.documentsDirectory();\nconst pendingPath=fm.joinPath(dir,'rk10-adaptive-pending.json');\nconst rulesPath=fm.joinPath(dir,'rk10-adaptive-rules.json');\nconst schedulePath=fm.joinPath(dir,'rk10-schedules-v1.json');\nfunction read(p,fallback){try{return JSON.parse(fm.readString(p));}catch(_){return fallback;}}\nfunction save(p,x){fm.writeString(p,JSON.stringify(x,null,2));}\nfunction backup(p){if(fm.fileExists(p)){const name=p.split('/').pop();fm.writeString(fm.joinPath(dir,'rk10-backup-'+name+'-'+Date.now()+'.bak'),fm.readString(p));}}\nfunction norm(s){return String(s||'').toLowerCase().replace(/[‐‑‒–—−]/g,'-').replace(/\\s+/g,' ').trim();}\nasync function choose(title,message,labels){const a=new Alert();a.title=title;a.message=message;labels.forEach(x=>a.addAction(x));a.addCancelAction('Скасувати');return await a.present();}\nasync function prompt(title,message,placeholder){const a=new Alert();a.title=title;a.message=message;a.addTextField(placeholder||'Введи значення');a.addAction('Підтвердити');a.addCancelAction('Скасувати');const r=await a.present();return r===0?a.textFieldValue(0).trim():null;}\nfunction time(s){let m=String(s).trim().match(/^(\\d{1,2})(?::|\\.)(\\d{2})$/);if(!m)return null;let h=+m[1],mi=+m[2];return h<=24&&mi<60&&(h!==24||mi===0)?60*h+mi:null;}\nfunction manualRanges(s){let entries=s.split(/[\\n;,]+/).map(x=>x.trim()).filter(Boolean), out=[];\n for(let item of entries){let m=item.match(/^(\\d{1,2}[:.]\\d{2})\\s*[-–—]\\s*(\\d{1,2}[:.]\\d{2})\\s+(on|off|є|немає|так|ні|1|0)$/iu);if(!m)return null;\n let a=time(m[1]),b=time(m[2]);if(a===null||b===null||b<=a)return null;\n out.push({from:a,to:b,on:/^(on|є|так|1)$/iu.test(m[3])});}\n if(!out.length||out[0].from!==0||out[out.length-1].to!==1440)return null;\n for(let i=1;i<out.length;i++)if(out[i].from!==out[i-1].to||out[i].on===out[i-1].on)return null;\n return out;\n}\nfunction isEmergencyMessage(s){\n const t=norm(s);\n return /(?:аварій[а-яіїєґ]*\\s+відключенн|аварі[яїієґ]|аварійн|планов[а-яіїєґ]*\\s+графік[а-яіїєґ]*\\s+не\\s+діють|⚡\\s*аварія\\s*дтек)/iu.test(t);\n}\nfunction effectiveKind(entry){\n // Repair classification of previously queued messages without touching any data.\n if(entry.kind==='schedule' && isEmergencyMessage(entry.message) &&\n    !/(?:графік|розклад)\\s+на\\s+(?:сьогодні|завтра)/iu.test(entry.message))return 'incident';\n return entry.kind;\n}\nasync function handle(entry){\n const selected=await choose('РК10 · '+effectiveKind(entry),(effectiveKind(entry)!==entry.kind?'Це аварійне повідомлення, а не плановий графік.\\n':'')+entry.reason+'\\n\\n'+entry.message.slice(0,900),['Підтвердити / виправити','Ігнорувати']);\n if(selected<0)return false;\n if(selected===1)return true;\n if(entry.kind==='status'){\n   const action=await choose('Що означає повідомлення?',entry.message.slice(0,500),['Світло зникло','Світло зʼявилось','Не є статусом']);\n   if(action<0)return false;if(action===2)return true;\n   const label=action===0?'off':'on';\n   const phrase=await prompt('Навчити розпізнавач','Введи характерну фразу, яка однозначно означає цей статус. Не вводь РК10, дату або час. Приклад: «електроживлення припинено». Вона використовуватиметься ТІЛЬКИ в рядку з РК10.','Фраза зі сповіщення');\n   if(phrase===null)return false;\n   const p=norm(phrase);\n   if(p.length<5||p.length>100||/[\\d]/.test(p)||/\\b(?:рк|rk|pk)\\s*10\\b/iu.test(p)){\n     await choose('Правило відхилено','Фраза має бути 5–100 символів, без цифр та назви РК10.',['Гаразд']);return false;\n   }\n   const lines=entry.message.split('\\n');\n   if(!lines.some(line=>/(?:рк|rk|pk)\\s*10\\b/iu.test(line)&&norm(line).includes(p))){\n     await choose('Не вдалося навчити','Фраза має дослівно бути в тому самому рядку, де зазначено РК10. Це обмеження захищає від хибних перемикань.',['Гаразд']);return false;\n   }\n   let rules=read(rulesPath,{});rules.status=Array.isArray(rules.status)?rules.status:[];\n   if(rules.status.some(r=>norm(r.phrase)===p&&r.value!==label)){\n     await choose('Конфлікт правил','Ця сама фраза вже навчена означати протилежний стан. Нове правило не записано.',['Гаразд']);return false;\n   }\n   if(!rules.status.some(r=>norm(r.phrase)===p&&r.value===label)){\n     backup(rulesPath);rules.status.push({phrase:p,value:label,created:Date.now()});save(rulesPath,rules);\n   }\n   await choose('Правило збережено','Майбутні повідомлення з цією фразою та РК10 будуть розпізнані. Минулу подію автоматично НЕ додано в історію, щоб не записати неправильний час. Для цього є «Відновити подію світла».',['Гаразд']);\n   return true;\n }\n if(effectiveKind(entry)==='schedule'){\n   const date=await prompt('Дата графіка','Дата у форматі РРРР-ММ-ДД.','2026-11-08');if(date===null)return false;\n   if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)||!Number.isFinite(new Date(date+'T00:00:00').getTime())||new Date(date+'T00:00:00').toLocaleDateString('sv-SE')!==date){await choose('Некоректна дата','Не зберігав нічого.',['Гаразд']);return false;}\n   const source=await prompt('Підтверди повний графік','Напиши всі інтервали через ; або з нового рядка. Формат: 00:00-07:00 off; 07:00-10:00 on; ... до 24:00. on = світло є, off = немає.','00:00-07:00 off; 07:00-10:00 on; ...');if(source===null)return false;\n   const ranges=manualRanges(source);if(!ranges){await choose('Графік не збережено','Інтервали мають без пропусків покривати 00:00–24:00 і чергувати on/off.',['Гаразд']);return false;}\n   let db=read(schedulePath,{schedules:{},incidents:[]});if(!db||typeof db!=='object')db={schedules:{},incidents:[]};db.schedules=db.schedules||{};\n   const conf=await choose('Зберегти підтверджений графік?',date+' · '+ranges.length+' інтервалів. Запис замінить графік за цю дату.',['Так, зберегти']);if(conf!==0)return false;\n   backup(schedulePath);db.schedules[date]={ranges,received:Date.now(),manual:true};save(schedulePath,db);\n   await choose('Готово','Підтверджений графік збережено. Це не нове універсальне правило парсингу: якщо формат знову зміниться, буде нове попередження.',['Гаразд']);return true;\n }\n if(effectiveKind(entry)==='incident'){\n   const action=await choose('Аварійне повідомлення','Вибери підтверджений зміст.',['Аварійне відключення діє','Аварію скасовано','Не стосується РК10']);if(action<0)return false;if(action===2)return true;\n   const date=await prompt('Дата аварії','Дата у форматі РРРР-ММ-ДД.','2026-11-08');if(date===null)return false;\n   if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)||new Date(date+'T00:00:00').toLocaleDateString('sv-SE')!==date){await choose('Некоректна дата','Дані не змінено.',['Гаразд']);return false;}\n   let db=read(schedulePath,{schedules:{},incidents:[]});db.incidents=Array.isArray(db.incidents)?db.incidents:[];\n   backup(schedulePath);db.incidents=db.incidents.filter(x=>x.date!==date);db.incidents.push({date,status:action===0?'active':'cancel',received:Date.now(),manual:true});save(schedulePath,db);return true;\n }\n return false;\n}\n// Migrate false alarms generated by older schedule parser, without modifying schedules or light history.\n// Only a queued *schedule parsing* error that contains a clear emergency statement\n// and does NOT contain a real 'schedule for today/tomorrow' header can be retired.\nfunction obsoleteEmergencyScheduleError(entry){\n if(!entry || entry.status!=='pending' || entry.kind!=='schedule')return false;\n const reason=norm(entry.reason);\n if(!/(?:не вдалося прочитати|не вдалося розпізнати|повн[а-яіїєґ]* графік|планов[а-яіїєґ]* графік)/iu.test(reason))return false;\n return effectiveKind(entry)==='incident';\n}\nlet items=read(pendingPath,[]);if(!Array.isArray(items))items=[];\nlet cleaned=0;\nfor(const entry of items){\n if(obsoleteEmergencyScheduleError(entry)){\n   entry.status='dismissed_false_schedule';\n   entry.reviewedAt=Date.now();\n   entry.resolution='Аварійне повідомлення, помилково записане старою версією як графік';\n   cleaned++;\n }\n}\nif(cleaned){backup(pendingPath);save(pendingPath,items);}\nlet outstanding=items.filter(x=>x.status==='pending');\nif(!outstanding.length){await choose('РК10 · Все добре',(cleaned?'Прибрано старих помилкових перевірок графіка: '+cleaned+'.\\n\\n':'')+'Немає неперевірених повідомлень. Якщо Telegram не надіслав сповіщення, скрипт не може визначити пропуск.',['Гаразд']);}\nelse{\n const selected=await choose('РК10 · Потрібна перевірка','Невідомих повідомлень: '+outstanding.length+(cleaned?'\\nВиправлено старих хибних сповіщень: '+cleaned:'')+'\\n\\nОстаннє: '+outstanding[outstanding.length-1].reason+'\\n'+outstanding[outstanding.length-1].message.slice(0,250),['Перевірити останнє']);\n if(selected===0){let obj=outstanding[outstanding.length-1];let done=await handle(obj);if(done){obj.status='reviewed';obj.reviewedAt=Date.now();save(pendingPath,items);}}\n}\nScript.complete();\n","Відновити подію світла.js":"// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: teal; icon-glyph: magic;\n// Scriptable — резервне внесення пропущених подій світла для РК10.\n// Не змінює планові графіки; використовує існуючі файли Світло вдома.\nconst fm = FileManager.local();\nconst dir = fm.documentsDirectory();\nconst historyPath = fm.joinPath(dir, 'light-history.json');\nconst statePath = fm.joinPath(dir, 'light-home.json');\nconst pad = n => String(n).padStart(2, '0');\nconst now = new Date();\nconst defaultDate = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;\nconst defaultTime = `${pad(now.getHours())}:${pad(now.getMinutes())}`;\n\nasync function notice(title, msg) {\n  const a = new Alert(); a.title = title; a.message = msg; a.addAction('OK'); await a.presentAlert();\n}\nasync function prompt() {\n  const a = new Alert();\n  a.title = 'Відновити подію РК10';\n  a.message = 'Вкажи точний час із Telegram. Це змінить історію фактичного світла.';\n  a.addTextField('Дата (РРРР-ММ-ДД)', defaultDate);\n  a.addTextField('Час (ГГ:ХХ)', defaultTime);\n  a.addAction('🟢 Світло з’явилося');\n  a.addAction('🔴 Світло зникло');\n  a.addCancelAction('Скасувати');\n  const choice = await a.presentAlert();\n  if (choice < 0 || choice > 1) return null;\n  return {status:choice===0?'on':'off', date:a.textFieldValue(0).trim(), time:a.textFieldValue(1).trim()};\n}\nfunction parseLocal(date,time) {\n  const m=/^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(date), t=/^(\\d{2}):(\\d{2})$/.exec(time);\n  if (!m || !t) return null;\n  const [Y,M,D,h,min]=[+m[1],+m[2],+m[3],+t[1],+t[2]];\n  if (Y<2020 || M<1 || M>12 || D<1 || D>31 || h>23 || min>59) return null;\n  const d=new Date(Y,M-1,D,h,min,0,0);\n  if (d.getFullYear()!==Y||d.getMonth()!==M-1||d.getDate()!==D||d.getHours()!==h||d.getMinutes()!==min)return null;\n  return d.getTime();\n}\nfunction readJSON(path,fallback) {\n  if (!fm.fileExists(path)) return fallback;\n  return JSON.parse(fm.readString(path));\n}\nconst req = await prompt();\nif (!req) { Script.complete(); }\nelse {\n  const at=parseLocal(req.date,req.time);\n  if (at===null || at>Date.now()+60000 || at<Date.now()-90*86400000) {\n    await notice('Час не прийнято','Введи коректну локальну дату й час не в майбутньому та не старші за 90 днів.');\n  } else {\n    try {\n      const original = readJSON(historyPath, []);\n      if(!Array.isArray(original))throw new Error('Історія має неправильний формат');\n      const hist=original.filter(x=>x && (x.status==='on'||x.status==='off') && Number.isFinite(x.at))\n                         .map(x=>({status:x.status,at:x.at})).sort((a,b)=>a.at-b.at);\n      if(hist.some(x=>Math.abs(x.at-at)<60000 && x.status!==req.status)) {\n        await notice('Конфлікт', 'На цю хвилину вже записаний протилежний стан. Історію не змінено.');\n      } else {\n        const candidate=hist.concat([{status:req.status,at}]).sort((a,b)=>a.at-b.at);\n        // Залишаємо першу з послідовних однакових подій, не вигадуючи перемикань.\n        const normalized=[];\n        for(const x of candidate) {\n          if(!normalized.length || normalized[normalized.length-1].status!==x.status)normalized.push(x);\n        }\n        const modified=JSON.stringify(normalized)!==JSON.stringify(hist);\n        if(!modified) {\n          await notice('Подія вже врахована', 'У цьому інтервалі стан уже такий самий. Додаткову подію не створено.');\n        } else {\n          const confirm = new Alert();\n          confirm.title='Підтвердити відновлення';\n          confirm.message=`${req.status==='on'?'Світло з’явилося':'Світло зникло'}: ${req.date} ${req.time}\\n\\nБуде оновлено історію та поточний стан із її останньої події. Перед змінами створиться резервна копія.`;\n          confirm.addAction('Зберегти'); confirm.addCancelAction('Скасувати');\n          if(await confirm.presentAlert()===0) {\n            const state=readJSON(statePath,{status:'unknown',since:null,lastOutage:null,lastSeen:null});\n            const stamp=Date.now();\n            if(fm.fileExists(historyPath))fm.copy(historyPath,fm.joinPath(dir,`light-history.backup-${stamp}.json`));\n            if(fm.fileExists(statePath))fm.copy(statePath,fm.joinPath(dir,`light-home.backup-${stamp}.json`));\n            const last=normalized[normalized.length-1];\n            const prev=normalized.length>1?normalized[normalized.length-2]:null;\n            const newState={...state,status:last.status,since:last.at};\n            if(last.status==='on' && prev && prev.status==='off')newState.lastOutage=Math.max(0,last.at-prev.at);\n            // lastSeen — час отримання реального сповіщення; не видаємо ручну правку за нове сповіщення.\n            fm.writeString(historyPath,JSON.stringify(normalized));\n            fm.writeString(statePath,JSON.stringify(newState));\n            await notice('Історію відновлено',`${req.status==='on'?'🟢 Світло з’явилося':'🔴 Світло зникло'} — ${req.date} ${req.time}.\\n\\nЗаписів в історії: ${normalized.length}. Резервні копії створено.`);\n          }\n        }\n      }\n    } catch(err) { await notice('Не вдалося зберегти',String(err)); }\n  }\n  Script.complete();\n}\n","Статистика 7 днів.js":"try{await importModule('Республіка · API').sync();}catch(e){console.log('API: '+e);}\n// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: deep-brown; icon-glyph: magic;\n// Scriptable — Статистика світла, 7 днів (MEDIUM)\n// Чорна тема. Нативний текст, без картинок.\n// Читає light-history-api-v2.json, який веде «Світло вдома».\n\nconst fm = FileManager.local();\nconst file = fm.joinPath(fm.documentsDirectory(), \"light-history-api-v2.json\");\nconst NOW = Date.now();\nconst C = {\n  bg: \"#000000\", text: \"#FFFFFF\", muted: \"#A3A3A3\",\n  green: \"#4ADE80\", red: \"#F87171\", tile: \"#303030\",\n  line: \"#242424\"\n};\n\nlet history = [];\ntry {\n  if (fm.fileExists(file)) {\n    const raw = JSON.parse(fm.readString(file));\n    if (Array.isArray(raw)) history = raw;\n  }\n} catch (e) {\n  console.log(\"Помилка читання історії: \" + e);\n}\n\nconst events = history.filter(e =>\n  e && (e.status === \"on\" || e.status === \"off\") &&\n  Number.isFinite(e.at) && e.at <= NOW\n).sort((a, b) => a.at - b.at);\n\nconst periods = [];\nfor (let i = 0; i < events.length; i++) {\n  const end = i + 1 < events.length ? events[i + 1].at : NOW;\n  if (end > events[i].at) {\n    periods.push({\n      start: events[i].at,\n      end,\n      status: events[i].status,\n      completed: i + 1 < events.length && events[i + 1].status === \"on\"\n    });\n  }\n}\n\nfunction overlap(a, b, c, d) {\n  return Math.max(0, Math.min(b, d) - Math.max(a, c));\n}\nfunction stats(a, b) {\n  let on = 0, off = 0;\n  for (const p of periods) {\n    const ms = overlap(a, b, p.start, p.end);\n    if (p.status === \"on\") on += ms;\n    else off += ms;\n  }\n  return { on, off, known: on + off };\n}\nfunction fmt(ms) {\n  const mins = Math.max(0, Math.floor(ms / 60000));\n  const h = Math.floor(mins / 60), m = mins % 60;\n  return h ? `${h} год ${m} хв` : `${m} хв`;\n}\nfunction write(parent, value, size, color = C.text, bold = false) {\n  const t = parent.addText(String(value));\n  t.font = bold ? Font.boldSystemFont(size) : Font.systemFont(size);\n  t.textColor = new Color(color);\n  t.lineLimit = 1;\n  t.minimumScaleFactor = 0.7;\n  return t;\n}\n\nconst todayStart = new Date(NOW);\ntodayStart.setHours(0, 0, 0, 0);\nconst weekStart = new Date(todayStart);\nweekStart.setDate(weekStart.getDate() - 6);\nconst days = [];\nfor (let i = 0; i < 7; i++) {\n  const date = new Date(weekStart);\n  date.setDate(weekStart.getDate() + i);\n  const next = new Date(date);\n  next.setDate(date.getDate() + 1);\n  days.push({\n    name: [\"Нд\", \"Пн\", \"Вт\", \"Ср\", \"Чт\", \"Пт\", \"Сб\"][date.getDay()],\n    ...stats(date.getTime(), Math.min(NOW, next.getTime()))\n  });\n}\nconst today = days[6];\nconst week = stats(weekStart.getTime(), NOW);\nconst outages = periods.filter(p =>\n  p.status === \"off\" && p.start >= weekStart.getTime() && p.start <= NOW\n);\nconst finished = outages.filter(p => p.completed);\nconst avg = finished.length\n  ? finished.reduce((sum, p) => sum + p.end - p.start, 0) / finished.length\n  : null;\n\nconst w = new ListWidget();\nw.backgroundColor = new Color(C.bg);\nw.setPadding(9, 12, 8, 12);\n\n// Заголовок\nconst head = w.addStack();\nhead.centerAlignContent();\nwrite(head, \"⚡\", 15, C.green, true);\nhead.addSpacer(5);\nwrite(head, \"Статистика світла\", 16, C.text, true);\nhead.addSpacer();\nwrite(head, \"7 днів\", 10, C.muted);\nw.addSpacer(7);\n\n// Дві рівні колонки з чотирма показниками\nfunction metric(row, caption, value) {\n  const box = row.addStack();\n  box.layoutVertically();\n  box.size = new Size(145, 31);\n  write(box, caption, 9, C.muted);\n  box.addSpacer(2);\n  write(box, value, 14, C.text, true);\n}\nlet row = w.addStack();\nmetric(row, \"Сьогодні без світла\", today.known ? fmt(today.off) : \"Немає даних\");\nrow.addSpacer();\nmetric(row, \"За 7 днів\", week.known ? fmt(week.off) : \"Немає даних\");\nw.addSpacer(4);\n\nrow = w.addStack();\nmetric(row, \"Відключень\", events.length ? String(outages.length) : \"—\");\nrow.addSpacer();\nmetric(row, \"Середня тривалість\", avg === null ? \"—\" : fmt(avg));\nw.addSpacer(5);\n\n// П'ятий показник — компактний окремий рядок\nconst light = w.addStack();\nlight.centerAlignContent();\nlight.backgroundColor = new Color(\"#171C19\");\nlight.cornerRadius = 5;\nlight.setPadding(3, 7, 3, 7);\nwrite(light, \"Сьогодні зі світлом\", 10, C.muted);\nlight.addSpacer();\nwrite(light, today.known ? fmt(today.on) : \"Немає даних\", 11, C.green, true);\nw.addSpacer(6);\n\n// Сім однакових колонок: назва дня завжди по центру своєї плитки\nconst chart = w.addStack();\nchart.layoutHorizontally();\nconst barWidth = 33, barHeight = 25;\n// Висота плитки = доба: зелений = підтверджене світло,\n// червоний = підтверджене відключення, сірий = немає даних.\nfor (let i = 0; i < 7; i++) {\n  if (i > 0) chart.addSpacer();\n  const day = days[i];\n  const col = chart.addStack();\n  col.layoutVertically();\n  col.size = new Size(barWidth, 39);\n\n  const track = col.addStack();\n  track.layoutVertically();\n  track.size = new Size(barWidth, barHeight);\n  track.backgroundColor = new Color(C.tile);\n  track.cornerRadius = 4;\n\n  if (!day.known) {\n    track.addSpacer();\n    const missing = track.addStack();\n    missing.size = new Size(barWidth, 12);\n    missing.addSpacer();\n    write(missing, \"—\", 10, C.muted);\n    missing.addSpacer();\n    track.addSpacer();\n  } else {\n    // Час доби йде ЗНИЗУ ВГОРУ: 00:00 унизу, 24:00 угорі.\n    // Порядок подій зберігаємо, змінюємо тільки візуальний напрям.\n    const start = new Date(weekStart);\n    start.setDate(weekStart.getDate() + i);\n    const next = new Date(start);\n    next.setDate(start.getDate() + 1);\n    const dayStart = start.getTime();\n    const dayEnd = next.getTime();\n    const fullDay = dayEnd - dayStart;\n\n    const segments = [];\n    let cursor = dayStart;\n    for (const p of periods) {\n      const a = Math.max(dayStart, p.start);\n      const b = Math.min(dayEnd, p.end);\n      if (b <= a) continue;\n      if (a > cursor) {\n        segments.push({ a: cursor, b: a, status: \"unknown\" });\n      }\n      segments.push({ a, b, status: p.status });\n      cursor = b;\n    }\n    if (cursor < dayEnd) {\n      segments.push({ a: cursor, b: dayEnd, status: \"unknown\" });\n    }\n\n    // Малюємо зверху вниз у зворотному хронологічному порядку.\n    // Верх — 24:00 (або майбутній час), низ — 00:00.\n    // Висоту рахуємо за межами інтервалів, без накопичення похибки.\n    let used = 0;\n    for (const seg of segments.reverse()) {\n      const toY = Math.round((dayEnd - seg.a) / fullDay * barHeight);\n      const height = Math.max(0, toY - used);\n      used = toY;\n      if (height === 0) continue;\n      if (seg.status === \"unknown\") {\n        track.addSpacer(height);\n      } else {\n        const part = track.addStack();\n        part.size = new Size(barWidth, height);\n        part.backgroundColor = new Color(\n          seg.status === \"on\" ? C.green : C.red\n        );\n      }\n    }\n    if (used < barHeight) track.addSpacer(barHeight - used);\n  }\n\n  col.addSpacer(2);\n  const dayRow = col.addStack();\n  dayRow.size = new Size(barWidth, 12);\n  dayRow.addSpacer();\n  const dayText = write(dayRow, day.name, 9, C.muted);\n  dayText.centerAlignText();\n  dayRow.addSpacer();\n}\n\nw.refreshAfterDate = new Date(NOW + 60000);\nScript.setWidget(w);\nif (config.runsInApp) await w.presentMedium();\nScript.complete();\n","Статистика місяць.js":"try{await importModule('Республіка · API').sync();}catch(e){console.log('API: '+e);}\n// Variables used by Scriptable.\n// These must be at the very top of the file. Do not edit.\n// icon-color: teal; icon-glyph: magic;\n// Scriptable · Чорна тема · Нативний чіткий текст\n// Читає історію з «Світло вдома». Не змінює її.\nconst fm=FileManager.local();\nconst file=fm.joinPath(fm.documentsDirectory(),\"light-history-api-v2.json\");\nconst now=Date.now();\nlet original=[];\ntry{\n  if(fm.fileExists(file)){\n    const x=JSON.parse(fm.readString(file));\n    if(Array.isArray(x))original=x;\n  }\n}catch(e){}\nconst events=original.filter(e=>e &&\n  (e.status===\"on\"||e.status===\"off\") &&\n  Number.isFinite(e.at)&&e.at<=now)\n  .sort((a,b)=>a.at-b.at);\nconst intervals=[];\nfor(let i=0;i<events.length;i++){\n  const a=events[i].at;\n  const b=Math.min(i+1<events.length?events[i+1].at:now,now);\n  if(b>a)intervals.push({a,b,status:events[i].status,\n    completed:i+1<events.length&&events[i+1].status===\"on\"});\n}\nfunction intersect(a,b,c,d){\n  return Math.max(0,Math.min(b,d)-Math.max(a,c));\n}\nfunction stats(a,b){\n  let off=0,on=0;\n  for(const x of intervals){\n    const ms=intersect(a,b,x.a,x.b);\n    if(x.status===\"off\")off+=ms;else on+=ms;\n  }\n  return {off,on,known:off+on};\n}\nfunction duration(ms){\n  const m=Math.max(0,Math.floor(ms/60000));\n  return Math.floor(m/60)+\" год \"+String(m%60).padStart(2,\"0\")+\" хв\";\n}\nfunction short(ms){\n  const m=Math.max(0,Math.floor(ms/60000));\n  return Math.floor(m/60)+\"г\"+String(m%60).padStart(2,\"0\");\n}\nconst P={\n  bg:\"#000000\",text:\"#FFFFFF\",muted:\"#A3A3A3\",\n  red:\"#F87171\",green:\"#4ADE80\",tile:\"#303030\",\n  empty:\"#161616\",dim:\"#858585\",divider:\"#3A3A3A\",\n  card:\"#272727\",good:\"#254A35\",low:\"#365E45\",\n  mid:\"#80612F\",high:\"#87413D\"\n};\nfunction text(parent,value,size,color=P.text,bold=false){\n  const t=parent.addText(String(value));\n  t.font=bold?Font.boldSystemFont(size):Font.systemFont(size);\n  t.textColor=new Color(color);\n  t.lineLimit=1;\n  t.minimumScaleFactor=0.6;\n  return t;\n}\nfunction centered(parent,value,size,color=P.text,bold=false){\n  const row=parent.addStack();\n  row.addSpacer();\n  text(row,value,size,color,bold);\n  row.addSpacer();\n}\nfunction separator(w){\n  const line=w.addStack();\n  line.size=new Size(0,1);\n  line.backgroundColor=new Color(P.divider);\n}\n\nconst today=new Date(now),year=today.getFullYear(),month=today.getMonth();\nconst first=new Date(year,month,1);\nconst endMonth=new Date(year,month+1,1);\nconst count=new Date(year,month+1,0).getDate();\nconst offset=(first.getDay()+6)%7;\nconst rowCount=Math.ceil((offset+count)/7);\nconst totals=stats(first.getTime(),Math.min(now,endMonth.getTime()));\nconst items=[];\nfor(let i=1;i<=count;i++){\n  const start=new Date(year,month,i).getTime();\n  const end=Math.min(now,new Date(year,month,i+1).getTime());\n  const x=stats(start,end);\n  items.push({...x,future:start>now,\n    partial:x.known>0&&x.known<end-start-60000});\n}\nconst name=first.toLocaleDateString(\"uk-UA\",{month:\"long\",year:\"numeric\"});\nconst w=new ListWidget();\nw.backgroundColor=new Color(P.bg);\nw.setPadding(11,13,10,13);\ntext(w,\"⚡ Статистика світла\",21,P.text,true);\nw.addSpacer(3);\ntext(w,name.charAt(0).toUpperCase()+name.slice(1),11,P.muted);\nw.addSpacer(9);\n\n// Верхня панель займає всю доступну ширину, як календар.\n// Гнучкі проміжки доповнюють ширину без масштабування тексту.\nconst summary=w.addStack();\nsummary.layoutHorizontally();\nsummary.backgroundColor=new Color(P.card);\nsummary.cornerRadius=9;\nsummary.setPadding(6,8,6,8);\n\nfunction metric(label,value,color){\n  const box=summary.addStack();\n  box.layoutVertically();\n  box.size=new Size(111,47);\n  text(box,label,10,P.muted);\n  box.addSpacer(5);\n  text(box,value,14,color,true);\n}\nfunction verticalDivider(){\n  const line=summary.addStack();\n  line.size=new Size(1,39);\n  line.backgroundColor=new Color(\"#484848\");\n}\nmetric(\"Без світла\",\n  totals.known?duration(totals.off):\"Немає даних\",P.red);\nsummary.addSpacer();\nverticalDivider();\nsummary.addSpacer(3);\nconst percent=summary.addStack();\npercent.layoutVertically();\npercent.size=new Size(63,47);\npercent.addSpacer(2);\nconst share=totals.known>0?\n  Math.round(totals.on/totals.known*100)+\"%\":\"—\";\ncentered(percent,share,21,totals.known>0?P.green:P.muted,true);\npercent.addSpacer(2);\ncentered(percent,\"зі світлом\",8,P.muted);\npercent.addSpacer(2);\nsummary.addSpacer(3);\nverticalDivider();\nsummary.addSpacer();\nmetric(\"Зі світлом\",\n  totals.known?duration(totals.on):\"Немає даних\",P.green);\nw.addSpacer(9);\nconst section=w.addStack();\ntext(section,\"Без світла за днями\",12,P.text,true);\nsection.addSpacer();\ntext(section,\"день / год\",9,P.muted);\nw.addSpacer(6);\n\n// Колонки по всій ширині: без лівого порожнього поля.\n// Ніякого DrawContext — лише нативний текст Scriptable.\nconst weekNames=[\"Пн\",\"Вт\",\"Ср\",\"Чт\",\"Пт\",\"Сб\",\"Нд\"];\nconst weekdayRow=w.addStack();\nfor(let i=0;i<7;i++){\n  if(i)weekdayRow.addSpacer();\n  const col=weekdayRow.addStack();\n  col.size=new Size(39,15);\n  centered(col,weekNames[i],10,P.muted,true);\n}\nw.addSpacer(5);\n\nconst height=rowCount===6?24:28;\nfor(let r=0;r<rowCount;r++){\n  const line=w.addStack();\n  for(let c=0;c<7;c++){\n    if(c)line.addSpacer();\n    const day=r*7+c-offset+1;\n    const cell=line.addStack();\n    cell.layoutVertically();\n    cell.size=new Size(39,height);\n    cell.cornerRadius=5;\n    if(day<1||day>count){\n      cell.backgroundColor=new Color(P.empty);\n      continue;\n    }\n    const x=items[day-1];\n    const unknown=x.future||x.known===0;\n    let background=P.tile;\n    if(!unknown){\n      const hours=x.off/3600000;\n      background=hours===0?P.good:hours<=3?P.low:\n        hours<=6?P.mid:P.high;\n    }\n    cell.backgroundColor=new Color(background);\n    cell.addSpacer(1);\n    centered(cell,day,10,unknown?P.dim:P.text);\n    cell.addSpacer(1);\n    centered(cell,unknown?\"—\":short(x.off)+(x.partial?\"*\":\"\"),\n      10,unknown?P.dim:P.text,true);\n    cell.addSpacer(1);\n  }\n  if(r<rowCount-1)w.addSpacer(3);\n}\nw.addSpacer(6);\ntext(w,\"* неповний день  ·  — немає даних\",9,P.muted);\nw.refreshAfterDate=new Date(now+60000);\nScript.setWidget(w);\nif(config.runsInApp)await w.presentLarge();\nScript.complete();\n"};

const API_MODULE="// Світло Республіка API v2.0.0 — локальні дані, приватний Bearer-токен у Keychain.\nconst fm=FileManager.local(),dir=fm.documentsDirectory();\nconst f=n=>fm.joinPath(dir,n);\nconst CONFIG=f('respublika-install-config.json');\nconst HIST=f('light-history-api-v2.json'),STATE=f('light-home-api-v2.json'),META=f('light-api-v2-meta.json');\nconst TOKEN_KEY='respublika-api-token-v2';\nconst read=(p,d)=>{try{return fm.fileExists(p)?JSON.parse(fm.readString(p)):d;}catch(_){return d;}};\nconst write=(p,v)=>fm.writeString(p,JSON.stringify(v));\nconst valid=a=>(Array.isArray(a)?a:[]).filter(e=>e&&(e.status==='on'||e.status==='off')&&Number.isFinite(e.at)&&e.at<=Date.now()+60000).sort((a,b)=>a.at-b.at);\nconst code=a=>({'Т4А':'t4a','ТР1':'tr1','ТР3':'tr3','РК2А':'rk2a','ТР5':'tr5','РК4':'rk4','РК6':'rk6','ТР4':'tr4','БШ7':'bsh7','БШ9':'bsh9','БШ10/8':'bsh10/8','РК10':'rk10','БШ8':'bsh8'})[a];\nconst same=(a,b)=>a.status===b.status&&Math.abs(a.at-b.at)<120000;\nfunction migrate(){\n const meta=read(META,{});\n if(meta.migrated)return;\n let combined=valid(read(HIST,[]));\n const inputs=['light-history.json','light-history-api-v2-test.json','light-history-api-v21-rk10.json'];\n for(const n of inputs){\n  const p=f(n);if(!fm.fileExists(p))continue;\n  // Back up source and target before modifying a single event.\n  const suffix='respublika-backup-v2-'+n;\n  const backup=f(suffix);if(!fm.fileExists(backup))fm.copy(p,backup);\n  combined=combined.concat(valid(read(p,[])));\n }\n if(fm.fileExists(HIST)&&!fm.fileExists(f('respublika-backup-v2-current-history.json')))fm.copy(HIST,f('respublika-backup-v2-current-history.json'));\n combined.sort((a,b)=>a.at-b.at);\n const out=[];\n for(const item of combined){\n  const event={status:item.status,at:item.at};\n  if(!out.length){out.push(event);continue;}\n  const last=out[out.length-1];\n  if(same(last,event))continue;\n  if(last.status!==event.status)out.push(event);\n  // Same-status duplicates are not additional power transitions.\n }\n write(HIST,out);\n write(META,{...meta,migrated:true,migratedAt:Date.now(),importedEvents:out.length});\n}\nfunction markUnavailable(message,now){\n const prev=read(STATE,{});\n write(STATE,{status:'unknown',since:null,lastOutage:prev.lastOutage??null,lastSeen:prev.lastSeen??null,apiError:String(message),lastConfirmed:prev.lastConfirmed??(prev.status==='on'||prev.status==='off'?{status:prev.status,since:prev.since}:null)});\n write(META,{...read(META,{}),lastAttempt:now,error:String(message),status:'unavailable'});\n}\nfunction apply(data,now,address){\n const sensors=(data&&Array.isArray(data.sensors)?data.sensors:[]).filter(s=>String(s.address||'').toLowerCase()===code(address));\n if(!sensors.length)throw Error('Для '+address+' немає доступних датчиків у API.');\n if(sensors.some(s=>!['on','off','recovering','no_link'].includes(s.state)||!Number.isFinite(Date.parse(s.since))))throw Error('Некоректні дані датчиків.');\n if(!sensors.every(s=>s.state===sensors[0].state)||!['on','off'].includes(sensors[0].state))throw Error('Датчики мають різні або невизначені стани.');\n const status=sensors[0].state;\n const since=Math.max(...sensors.map(s=>Date.parse(s.since)));\n if(since>now+60000)throw Error('Дата стану у майбутньому.');\n const events=valid(read(HIST,[]));const last=events[events.length-1];\n let issue=null;\n if(!last)events.push({status,at:since});\n else if(last.status!==status){\n  if(since>last.at)events.push({status,at:since});\n  else issue='Конфлікт часу: історію не змінено';\n }else if(since>last.at+120000){\n  // The same status with a later start may hide intermediate flips.\n  issue='Можливі пропущені перемикання між перевірками API';\n }\n const cutoff=now-90*86400000;const boundary=events.findIndex(e=>e.at>=cutoff);\n const saved=boundary>1?events.slice(boundary-1):events;\n write(HIST,saved);\n const prior=saved.length>1?saved[saved.length-2]:null,tail=saved[saved.length-1];\n const prev=read(STATE,{});\n const lastOutage=status==='on'&&prior&&tail&&prior.status==='off'&&tail.status==='on' ? Math.max(0,tail.at-prior.at):prev.lastOutage??null;\n write(STATE,{status,since,lastSeen:now,lastOutage,apiSource:'api',apiError:null,warning:issue});\n write(META,{...read(META,{}),lastAttempt:now,lastSuccess:now,error:null,status:issue?'warning':'ok',warning:issue,events:saved.length});\n return {ok:true,warning:issue};\n}\nasync function sync(){\n const now=Date.now();\n try{migrate();}catch(e){console.log('Не вдалося перенести історію: '+e);markUnavailable('Помилка міграції історії: '+e,now);return {ok:false};}\n const config=read(CONFIG,{}),address=config.address,meta=read(META,{});\n if(!code(address)){markUnavailable('Невідома адреса — запусти INSTALL.js',now);return {ok:false};}\n if(meta.lastAttempt && now-meta.lastAttempt<45000){\n  if(meta.lastSuccess && now-meta.lastSuccess>10*60000){markUnavailable('Дані API застаріли',now);return {ok:false};}\n  return {ok:!meta.error,cached:true};\n }\n write(META,{...meta,lastAttempt:now});\n try{\n  if(!Keychain.contains(TOKEN_KEY))throw Error('Відсутній API-токен. Запусти INSTALL.js.');\n  const req=new Request('https://chatbot.respublika.pp.ua/api/v1/light');\n  req.method='GET';req.timeoutInterval=15;req.headers={Authorization:'Bearer '+Keychain.get(TOKEN_KEY),Accept:'application/json'};\n  const body=await req.loadString(),http=req.response&&req.response.statusCode;\n  if(http===401)throw Error('401: перевір персональний API-токен у кабінеті мешканця.');\n  if(http===429)throw Error('429: забагато запитів до API.');\n  if(http!==200)throw Error('API HTTP '+http);\n  return apply(JSON.parse(body),now,address);\n }catch(e){markUnavailable(e.message||String(e),now);return {ok:false,error:String(e)};}\n}\nmodule.exports={sync,migrate};";
const OUTPUT_NAMES=["Світло вдома.js", "Світло вдома - Lock.js", "Імпорт графіка.js", "Графік сьогодні+завтра.js", "План vs Факт.js", "Перевірка повідомлень.js", "Відновити подію світла.js", "Статистика 7 днів.js", "Статистика місяць.js"];
function pattern(a){
 const m=a.match(/^(РК|ТР|БШ|Т)(.*)$/);if(!m)throw new Error('Невідома адреса');
 const prefix={'РК':'[РP][КK]','ТР':'[ТT][РP]','БШ':'[БB][ШШ]','Т':'[ТT]'}[m[1]];
 const suffix=[...m[2]].map(c=>c==='А'?'[АA]':c==='/'?'\\/':c).join('');
 return '(?:^|[^\\p{L}\\p{N}])#?\\s*'+prefix+'\\s*'+suffix+'(?![\\p{L}\\p{N}])';
}
function adapt(src,address,name){
 let s=src.replace(/rk10-/g,'respublika-').replace(/РК10/g,address);
 if(name==='Світло вдома.js'){
  const before='const rk10=/#?\\s*[РP][КK]\\s*10(?![\\p{L}\\p{N}])/iu;';
  if(!s.includes(before))throw new Error('Шаблон статусу змінився');
  s=s.replace(before,'const rk10=new RegExp('+JSON.stringify(pattern(address))+',"iu");');
 }
 if(name==='Імпорт графіка.js'){
  const before='function isRK10(s){return /(?:^|[^\\p{L}\\p{N}])(?:рк|pk|rk)\\s*10(?![\\p{L}\\p{N}\\/])/iu.test(s);}';
  if(!s.includes(before))throw new Error('Шаблон імпортера змінився');
  s=s.replace(before,'function isRK10(s){return ADDRESS_RE.test(s);}');
  const beforeAddr="const ADDRESS = '"+address+"';";
  if(!s.includes(beforeAddr))throw new Error('Не знайдено адресу в імпортері');
  s=s.replace(beforeAddr,beforeAddr+'\nconst ADDRESS_RE=new RegExp('+JSON.stringify(pattern(address))+',"iu");');
 }
 if(name==='Перевірка повідомлень.js'){
  const anchor='const fm=FileManager.local(),dir=fm.documentsDirectory();';
  if(!s.includes(anchor))throw new Error('Шаблон перевірки змінився');
  s=s.replace(anchor,anchor+'\nconst ADDRESS_RE=new RegExp('+JSON.stringify(pattern(address))+',"iu");');
  const reject='/(?:\\b(?:рк|rk|pk)\\s*10\\b)/iu'; // not used, see literal replacements below
  const patternP='/\\b(?:рк|rk|pk)\\s*10\\b/iu.test(p)';
  const patternL='/(?:рк|rk|pk)\\s*10\\b/iu.test(line)';
  if(!s.includes(patternP)||!s.includes(patternL))throw new Error('Правила навчання змінилися');
  s=s.replace(patternP,'ADDRESS_RE.test(p)').replace(patternL,'ADDRESS_RE.test(line)');
 }
 return s;
}
async function show(title,message){let a=new Alert();a.title=title;a.message=message;a.addAction('Гаразд');await a.presentAlert();}
async function main(){
 const a=new Alert();a.title='Світло Республіка · API v2.0';
 a.message='Перед встановленням отримайте особистий API-токен у кабінеті https://chatbot.respublika.pp.ua/resident/. Оберіть адресу:';
 for(const addr of ADDRESSES)a.addAction(addr);a.addCancelAction('Скасувати');
 const idx=await a.presentAlert();if(idx<0)return;
 const address=ADDRESSES[idx];
 const t=new Alert();t.title='Персональний API-токен';
 t.message='Відкрийте https://chatbot.respublika.pp.ua/resident/, увійдіть через Telegram, підтвердьте доступ мешканця та створіть токен. Він зберігатиметься тільки в Keychain цього iPhone. Нікому його не надсилайте.';
 t.addTextField('rsp_…',Keychain.contains('respublika-api-token-v2')?Keychain.get('respublika-api-token-v2'):'');
 t.addAction('Продовжити');t.addCancelAction('Скасувати');
 if(await t.presentAlert()!==0)return;
 const token=t.textFieldValue(0).trim();
 if(!/^rsp_[A-Za-z0-9_-]{8,}$/.test(token)){await show('Некоректний токен','Уведіть персональний токен із кабінету мешканця, який починається з rsp_.');return;}
 // Verify token AND availability for this address before touching installed scripts.
 let data;
 try{
  const r=new Request('https://chatbot.respublika.pp.ua/api/v1/light');
  r.headers={Authorization:'Bearer '+token,Accept:'application/json'};r.timeoutInterval=15;
  data=JSON.parse(await r.loadString());
  if(!r.response||r.response.statusCode!==200)throw Error('HTTP '+(r.response&&r.response.statusCode));
  const code={'Т4А':'t4a','ТР1':'tr1','ТР3':'tr3','РК2А':'rk2a','ТР5':'tr5','РК4':'rk4','РК6':'rk6','ТР4':'tr4','БШ7':'bsh7','БШ9':'bsh9','БШ10/8':'bsh10/8','РК10':'rk10','БШ8':'bsh8'}[address];
  if(!data.sensors||!data.sensors.some(s=>String(s.address).toLowerCase()===code))throw Error('API не повернув датчиків для '+address+'. Зверніться до адміністратора бота.');
 }catch(e){await show('Не вдалося перевірити API','Скрипти не змінено. '+e);return;}
 const scripts={};for(const name of OUTPUT_NAMES)scripts[name]=adapt(SOURCES[name],address,name);
 const cloud=FileManager.iCloud(),dest=cloud.documentsDirectory(),prefix='Республіка · ';
 const names=OUTPUT_NAMES.map(n=>prefix+n);
 const planned=names.map(n=>cloud.joinPath(dest,n));
 const confirm=new Alert();confirm.title='Установити v2.0 для '+address;
 confirm.message='Заміниться код '+planned.filter(p=>cloud.fileExists(p)).length+' чинних скриптів. Локальні файли історії та графіків не видаляються. API замінює Telegram для фактичного стану, Telegram лишається для графіків. Створіть резервну копію Scriptable, якщо змінювали скрипти вручну.';
 confirm.addAction('Установити');confirm.addCancelAction('Скасувати');
 if(await confirm.presentAlert()!==0)return;
 // Preserve local history, schedules and prior scripts. No deletion or automatic cleanup.
 const fm=FileManager.local(),root=fm.documentsDirectory();
 const conf=fm.joinPath(root,'respublika-install-config.json');
 const backup=fm.joinPath(root,'respublika-backup-v2-install-config.json');
 if(fm.fileExists(conf)&&!fm.fileExists(backup))fm.copy(conf,backup);
 const history=fm.joinPath(root,'light-history.json'),historyBackup=fm.joinPath(root,'respublika-backup-v2-light-history.json');
 if(fm.fileExists(history)&&!fm.fileExists(historyBackup))fm.copy(history,historyBackup);
 const snapshot={version:VERSION,address,installedAt:Date.now()};
 Keychain.set('respublika-api-token-v2',token);
 for(const name of OUTPUT_NAMES)cloud.writeString(cloud.joinPath(dest,prefix+name),scripts[name]);
 cloud.writeString(cloud.joinPath(dest,'Республіка · API.js'),API_MODULE);
 fm.writeString(conf,JSON.stringify(snapshot,null,2));
 try{await importModule('Республіка · API').sync();}catch(e){console.log('Початкова синхронізація: '+e);}
 await show('Установлено для '+address,'API v2.0 встановлено. Додайте віджети «Республіка · …». Для графіків залиште ТІЛЬКИ автоматизацію Telegram → «Республіка · Імпорт графіка». Стару Telegram-автоматизацію стану вимкніть. Історія збережена.');
}
try{await main();}catch(e){await show('Помилка встановлення',String(e&&e.stack||e));}
Script.complete();
